    explanation: '静力学平衡 dp/dz = −ρg を鉛直積分すると、単位面積あたりの気柱質量は地表気圧 p₀ を重力加速度 g で割った p₀/g に等しくなる。これに地球全表面積（約5.1×10¹⁴ m²）を掛けると大気全質量は約5.3×10¹⁸ kgと算出でき、地球質量（約6×10²⁴ kg）のごく一部にすぎない。\n\n単位面積あたりの気柱質量が p₀/g で求められることは、地上気圧が上空の空気の重さそのものであるという静力学平衡の意味を端的に示している。この関係は可降水量の算出など、鉛直積分量を扱う場面でも同じ形で使われる。\n\n【図解】大気の質量の見積もり\n　量｜値｜役割\n　地上平均気圧｜約1013 hPa｜気柱の重さ\n　重力加速度｜約9.8 m/s²｜p₀/g で単位面積質量\n　地球の表面積｜約5.1×10¹⁴ m²｜全球へ拡張\n　大気の全質量｜約5×10¹⁸ kg｜地球質量のごく一部\n　⇒ 単位面積あたりでは約10⁴ kg、すなわち約10 tの空気が乗っている\n　⚠ 大気質量を地球質量と同程度とするのは6桁以上の誤り。',
