    choices: [
      { key: 'A', text: '状態曲線（環境大気の気温の高度分布）より気塊曲線（地上から断熱的に持ち上げた空気塊の気温の高度分布）が高温側にある高度では、空気塊は周囲より軽く正の浮力を受けて上昇を続けやすい。', explanation: '正しい。空気塊の気温が周囲（環境）の気温より高ければ、同じ気圧下で空気塊の密度は周囲より小さくなり（アルキメデスの原理に相当する浮力）、上向きの浮力を受けて上昇が加速される。' },
      { key: 'B', text: '状態曲線と気塊曲線が完全に一致する高度がある場合、その高度では常に対流が発生する。', explanation: '誤り。両曲線が一致する高度は浮力がゼロとなる高度（例えば平衡高度）を示すにすぎず、対流の発生そのものを保証するものではない。' },
      { key: 'C', text: '気塊曲線は常に状態曲線より低温側に位置し、いかなる高度でも空気塊が浮力を受けることはない。', explanation: '誤り。CAPEが存在する状況では、自由対流高度以上で気塊曲線が状態曲線より高温側（浮力が正）になる層が存在する。' },
      { key: 'D', text: 'エマグラムは気圧を横軸、気温を縦軸にとった図であり、状態曲線と気塊曲線の比較はできない。', explanation: '誤り。エマグラムは気温と気圧（対数目盛）を軸にとった熱力学図であり、状態曲線と気塊曲線を重ねて描き比較することで大気の安定度やCAPE・CINを診断するために用いられる代表的な図である。' },
    ],
    correctKey: 'A',
    explanation: 'エマグラムでは環境の気温分布（状態曲線）と地上から断熱的に持ち上げた空気塊の気温変化（気塊曲線）を重ねて描く。気塊曲線が状態曲線より高温側にある層では正の浮力が働き上昇が加速され、この層の面積（気温差の積分）がCAPEに対応する。\n\n両曲線の交点のうち下側が自由対流高度 LFC、上側が平衡高度 EL にあたり、その間の面積が CAPE、LFC より下で気塊が冷たい部分の面積が CIN である。エマグラムは横軸に気温、縦軸に気圧（対数目盛）をとる図である。\n\n【図解】エマグラム上の位置関係\n　高度｜二つの曲線の関係｜意味\n　LCL｜気塊が飽和する高度｜雲底\n　LFC｜気塊が状態曲線を上回る点｜浮力が正に転じる\n　EL｜再び下回る点｜雲頂のめやす\n　⇒ LFC と EL の間の面積が CAPE に対応する\n　⚠ エマグラムは横軸が気温、縦軸が気圧。軸の取り違えに注意する。',
