    correctKey: 'A',
    explanation: 'リフティング指数（LI）は地上の代表的な空気塊を断熱的に500 hPa面まで持ち上げたときの気塊気温と、実際の500 hPa環境気温との差（環境−気塊）で定義される。LIが負で絶対値が大きいほど不安定（対流の発達しやすさ）を示し、日々の大気安定度診断に広く利用される。\n\nLI は差の取り方が環境気温から気塊気温を引く向きなので、気塊が暖かいほど負に大きくなる。目安として0以上は安定、−3〜0は対流の可能性、−6以下は激しい対流の可能性が高い。ショワルターの安定指数が850 hPa の空気塊を用いるのに対し、LI は地上付近の空気塊を用いる点が異なる。\n\n【図解】LI の目安\n　LI の値｜安定度｜想定される現象\n　0以上｜安定｜対流は起きにくい\n　−3〜0｜やや不安定｜にわか雨や雷雨\n　−6〜−3｜不安定｜激しい雷雨\n　−6以下｜非常に不安定｜激しい対流や突風\n　⇒ 起点の空気塊が地上付近か850 hPa かで LI と SSI が区別される\n　⚠ 「正で大きいほど不安定」は逆。負の値ほど不安定を示す。',
