    question: '準地衡風オメガ方程式における静的安定度パラメータ（S）の役割に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '静的安定度パラメータSは温位の鉛直勾配に対応する量であり、Sが大きい（大気が安定である）ほど、同じ強制力（渦度移流や温度移流の鉛直変化）に対して生じる鉛直流（上昇流・下降流）は弱められる傾向がある。', explanation: '正しい。準地衡風オメガ方程式は S∇²ω + f₀²∂²ω/∂p² = (強制項) という形で表され、静的安定度Sが大きいほど（大気が安定なほど）左辺のS∇²ωの項が大きくなり、同じ強制項に対して解かれる鉛直流ωの大きさは相対的に小さくなる。' },
      { key: 'B', text: '静的安定度パラメータSは常に負の値をとる。', explanation: '誤り。通常の（安定な）対流圏の大気ではSは正の値をとる。Sが負になるのは絶対不安定な成層の場合である。' },
      { key: 'C', text: '静的安定度パラメータSは風速のみに依存し、気温の鉛直分布とは無関係である。', explanation: '誤り。静的安定度パラメータSは気温（あるいは温位）の鉛直分布に基づいて定義される量であり、風速そのものとは直接関係しない。' },
      { key: 'D', text: 'Sが大きいほど、同じ強制力に対して生じる鉛直流はより強くなる。', explanation: '誤り。Sが大きい（安定である）ほど鉛直運動に対する抵抗が大きくなるため、生じる鉛直流はより弱くなる。' },
    ],
    correctKey: 'A',
    explanation: '準地衡風オメガ方程式では静的安定度パラメータS（≈−(RT/p)∂lnθ/∂p に相当）が鉛直流ωに対する係数として現れ、Sが大きい（大気が安定）ほど、同じ渦度移流・温度移流の強制に対して生じる鉛直流は弱くなる。逆に大気が不安定に近い（Sが小さい）ほど、弱い強制力でも強い鉛直流が生じやすい。\n\n静的安定度パラメータが分母側に効くため、同じ強制でも安定な大気では鉛直流が抑えられ、不安定な大気では小さな強制で強い上昇流が生じる。前線帯のように安定度が低い領域で降水が集中しやすいのはこのためである。\n\n【図解】静的安定度と鉛直流\n　安定度パラメータ S｜大気の状態｜同じ強制での鉛直流\n　大きい｜安定｜弱い\n　小さい｜不安定に近い｜強い\n　符号｜安定な大気では正｜温位の鉛直勾配に対応\n　⇒ 鉛直流の強さは強制の大きさと安定度の両方で決まる\n　⚠ 「S が大きいほど鉛直流が強い」は逆。安定なほど鉛直流は抑えられる。',
