    question: '熱力学第一法則を断熱変化（dQ=0）の空気塊に適用した場合の記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '断熱変化では cp dT − α dp = 0（cpは定圧比熱、αは比容、dpは気圧変化）が成り立ち、この式を静力学平衡の関係と組み合わせて積分すると乾燥断熱減率（dT/dz=−g/cp）やポアソンの式（温位保存則）が導かれる。', explanation: '正しい。熱力学第一法則 dQ=cpdT−αdp（エンタルピー形）において断熱変化（dQ=0）を仮定すると cpdT=αdp となり、これに静力学平衡 dp=−ρg dz と状態方程式 α=1/ρ=RdT/p を組み合わせることで、乾燥断熱減率やポアソンの式（θ一定）が導出される。' },
      { key: 'B', text: '断熱変化では空気塊への熱の出入りがあるため、dQは常にゼロではない値をとる。', explanation: '誤り。「断熱」とは定義上、外部との熱のやり取りがない過程（dQ=0）を指す。熱の出入りがある場合は非断熱過程と呼ばれ、断熱変化とは区別される。' },
      { key: 'C', text: 'この式から、断熱的に上昇する空気塊は気圧が下がっても気温は変化しないことがわかる。', explanation: '誤り。dQ=0でもcpdT=αdpの関係から、気圧が変化（低下）すれば気温も変化（低下）する。気温が変化しないのは等温変化の場合であり、断熱変化とは異なる。' },
      { key: 'D', text: '断熱変化における温度変化率は、気体定数Rdのみに依存し比熱cpとは無関係である。', explanation: '誤り。乾燥断熱減率の導出式（dT/dz=−g/cp）に示される通り、断熱変化における温度変化率は比熱cpに依存する量である。' },
    ],
    correctKey: 'A',
    explanation: '熱力学第一法則 dQ=cpdT−αdp において断熱過程（dQ=0）を考えると cpdT=αdp となり、これと静力学平衡・状態方程式を組み合わせることで乾燥断熱減率（Γd=g/cp≈9.8 °C/km）やポアソンの式（θ=T(1000/p)^(Rd/cp)、断熱過程でθ保存）が導出される。\n\n断熱変化では熱の出入りがないので、空気塊の内部エネルギーの変化は膨張や圧縮の仕事だけで生じる。上昇して気圧が下がれば膨張の仕事をしたぶん気温が下がり、下降すれば圧縮されて気温が上がる。この基本が乾燥断熱減率と温位の両方を導く。\n\n【図解】断熱変化から導かれるもの\n　出発点｜条件｜導かれる結果\n　熱力学第一法則｜dQ＝0｜cpdT＝αdp\n　静力学平衡を代入｜dp＝−ρgdz｜Γd＝g/cp≈9.8 ℃/km\n　積分｜基準1000 hPa｜θ＝T(1000/p)^0.286\n　⇒ 断熱過程では温位が保存されることが式から導かれる\n　⚠ 「断熱なら気圧が下がっても気温は変わらない」は誤り。膨張により必ず下がる。',
