    explanation: '環境減率（気温減率）は実際に観測される環境大気の気温の高度変化率であり、空気塊を断熱的に上昇・下降させたときの温度変化率である断熱減率（乾燥断熱減率・湿潤断熱減率）とは明確に区別される概念である。両者を比較することで大気の安定・不安定が判定される。\n\n環境減率は実際に観測される値なので、逆転層のように負の値をとることもあれば、晴天日の地表直上のように乾燥断熱減率を超えることもある。断熱減率は空気塊の性質で決まる理論値であり、両者は別物である。\n\n【図解】環境減率と断熱減率\n　量｜性格｜値の変動\n　環境減率｜観測される実際の値｜場所と時刻で大きく変わる\n　乾燥断熱減率｜理論値 g/cp｜約9.8 ℃/km で一定\n　湿潤断熱減率｜理論値｜気温により4〜9 ℃/km\n　⇒ 環境減率と断熱減率を比べることで安定度が判定できる\n　⚠ 環境減率が常に乾燥断熱減率に等しいとするのは、二つの概念の混同である。',
    difficulty: 'basic',
    examYear: '令和3年',
