    explanation: 'ICAO国際標準大気は地上気温15 °C・気圧1013.25 hPaを基準とし、対流圏（地上〜11 km）では気温減率6.5 °C/kmで気温が低下し、11〜20 km（成層圏下部）では気温が−56.5 °Cで一定と定義される、航空機の高度計や気象観測の基準として用いられるモデル大気である。\n\n国際標準大気は実際の大気の平均像を単純化したモデルで、航空機の高度計の較正や性能比較の基準として使われる。実際の大気はこれから外れるため、高度計は現地の気圧補正値（QNHなど）を用いて調整する必要がある。\n\n【図解】国際標準大気の主な諸元\n　項目｜値｜適用範囲\n　地上気温｜15 ℃｜海面高度\n　地上気圧｜1013.25 hPa｜海面高度\n　気温減率｜6.5 ℃/km｜0〜11 km\n　11〜20 km の気温｜−56.5 ℃で一定｜成層圏下部\n　⇒ 標準大気はあくまで基準であり、実際の大気とは異なる\n　⚠ 地上気圧の基準を1000 hPa とするのは誤り。1013.25 hPa である。',
