    explanation: '湿数（T−Td）は空気の湿り具合を表す量で、値が小さいほど飽和に近い（湿った）状態を示す。実技試験では700 hPa面などの湿数分布から「湿域」（おおむね3 °C以下が目安）を読み取り、大雨や上層雲の広がりを診断する手法が用いられる。\n\n湿数は定義上ゼロ以上の値しかとらず、ゼロが飽和を意味する。実技では700 hPa の湿数分布で中層の湿りを、850 hPa で下層の湿りを見て、上昇流域と重なるところを降水域と判断する。\n\n【図解】湿数による湿りの判断\n　湿数｜湿りの程度｜想定される状態\n　0 ℃｜飽和｜雲の中\n　3 ℃以下｜湿域｜雲や降水がある\n　10 ℃以上｜乾域｜晴天\n　⇒ 700 hPa の湿域と上昇流域が重なる領域が降水の目安になる\n　⚠ 湿数は小さいほど湿っている。「大きいほど湿っている」は逆である。',
