    explanation: '層厚の式 ΔZ＝(Rd Tmean/g)ln(p1/p2) は静力学平衡と状態方程式の帰結であり、層厚は層内の平均気温（正確には仮温度）に比例する。このため1000-500 hPa層厚は下層〜中層の平均気温の指標として天気図解析で広く用いられ、寒気の強さの目安（層厚が薄いほど寒気が強い）として利用される。\n\n層厚が平均気温に比例するという性質から、高層天気図では層厚の等値線が等温線と同じ意味をもつ。1000〜500 hPa 層厚では約5400 mが雨雪判別のめやすとして用いられる。\n\n【図解】層厚の式の読み方\n　要素｜層厚への効き方｜意味\n　平均気温 Tmean｜比例｜暖気ほど厚い\n　気圧比 ln(p1/p2)｜比例｜層の取り方で決まる\n　水蒸気｜仮温度で補正｜湿るほどわずかに厚い\n　⇒ 層厚が薄い領域が寒気の中心を示す\n　⚠ 「気温が高いほど薄くなる」は逆。暖気ほど層厚は大きくなる。',
