    subjectName: '予報業務に関する一般知識',
    question: '過冷却水面上と氷面上の飽和水蒸気圧の差に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '0 °C未満の気温では過冷却水面上の飽和水蒸気圧の方が氷面上の飽和水蒸気圧より常に高く、両者の差はおよそ−12 °C付近で最大となる。', explanation: '正しい。過冷却水は氷より分子が蒸発しやすい（自由エネルギーが高い）ため、同じ気温では水面上の飽和水蒸気圧の方が氷面上より高い。この差は気温の低下とともに拡大するが、ある温度（およそ−12 °C付近）で最大となり、それより低温側では再び差が縮小する。' },
      { key: 'B', text: '氷面上の飽和水蒸気圧は水面上の飽和水蒸気圧より常に高い。', explanation: '誤り。関係が逆である。過冷却水面上の飽和水蒸気圧の方が氷面上より高い。この差がバーグロン（氷晶）過程の駆動力となる。' },
      { key: 'C', text: '過冷却水面と氷面の飽和水蒸気圧の差は気温が低いほど単調に拡大し続け、上限は存在しない。', explanation: '誤り。両者の差はおよそ−12 °C付近で最大となり、それより低温側ではむしろ差が縮小する（単調に拡大し続けるわけではない）。' },
      { key: 'D', text: '過冷却水面と氷面の飽和水蒸気圧の差は0 °C以上の気温でのみ生じる現象である。', explanation: '誤り。過冷却水と氷の飽和水蒸気圧差は定義上0 °C未満（過冷却域）でのみ意味を持つ現象であり、0 °C以上では過冷却水そのものが存在しない。' },
    ],
    correctKey: 'A',
    explanation: '過冷却水面上の飽和水蒸気圧は氷面上より常に高く、この差はおよそ−12 °C付近で最大となる。これは氷晶過程（バーグロン過程）による雲粒の急成長が特に発達しやすい温度帯があることを意味し、着氷や降水粒子の成長を考える上で実技的にも重要な知見である。\n\nこの差は気温が下がるにつれて増えていくが、−12 ℃付近で最大となったあとは絶対量そのものが小さくなるため縮小に転じる。0 ℃以上では過冷却水も氷も同時には存在しないので、この差は問題にならない。\n\n【図解】水面上と氷面上の飽和水蒸気圧\n　気温｜水面上｜氷面上\n　0 ℃｜6.11 hPa｜6.11 hPa\n　−12 ℃｜約2.44 hPa｜約2.17 hPa\n　−20 ℃｜約1.25 hPa｜約1.03 hPa\n　−40 ℃｜約0.19 hPa｜約0.13 hPa\n　⇒ 差が最大となる−12 ℃前後で氷晶の成長が最も速い\n　⚠ 「氷面上のほうが高い」は逆。また差は際限なく拡大するわけではない。',
    difficulty: 'advanced',
