    explanation: '霧は発生機構により放射霧（夜間の地表放射冷却）、移流霧（暖湿気の移流による冷却、海霧など）、蒸気霧（冷気が暖かい水面上に流入）、滑昇霧（湿潤空気の山地斜面上昇による断熱冷却）などに分類される。それぞれ発生しやすい季節・時間帯・地形条件が異なるため、実技解析でも区別して扱われる。\n\n蒸気霧は冷たい空気が暖かい水面上に流入して、水面からの蒸発で水蒸気が過飽和になって生じるもので、川霧や冬の海面の気嵐がこれにあたる。滑昇霧は山地斜面を這い上がる空気の断熱冷却によるもので、山岳地でよく見られる。\n\n【図解】霧の種類と発生条件\n　種類｜冷却や加湿の機構｜典型例\n　放射霧｜夜間の放射冷却｜内陸の盆地の朝霧\n　移流霧｜暖湿気が冷たい面上を移動｜北海道沖の海霧\n　蒸気霧｜冷気が暖かい水面上へ｜川霧・気嵐\n　滑昇霧｜斜面上昇による断熱冷却｜山地の霧\n　⇒ 冷やして飽和させるか、水蒸気を加えて飽和させるかで分類できる\n　⚠ 蒸気霧は冷気が暖かい水面上に流入して生じる。暖気と冷水面の組み合わせは移流霧。',
