    explanation: '降水粒子の相は地上気温だけでなく、落下経路全体の気温履歴（特に0 °C以上の層の厚さ）に依存する。融解には融解熱の吸収を伴うため、地上付近が0 °Cをやや上回っていても融解層が薄ければ雪やみぞれとして観測されることがあり、大雪や積雪の予報ではこの鉛直構造の把握が重要となる。\n\n融解には熱の吸収を伴うため、融解が起きている層では気温が0 ℃付近に保たれやすく、レーダーではブライトバンドとして観測される。地上気温が2〜3 ℃でも、湿度が低く上空の融解層が薄ければ雪のまま降ることがある。\n\n【図解】降水の相と気温分布\n　上空の気層｜地上気温｜地上での相\n　全層が0 ℃未満｜0 ℃未満｜雪\n　薄い正温度層｜0〜2 ℃程度｜みぞれや湿った雪\n　厚い正温度層｜2 ℃以上｜雨\n　下層に強い冷気層｜0 ℃未満｜雨氷や凍雨\n　⇒ 判断には地上気温だけでなく落下経路全体の気温分布が要る\n　⚠ 融解は熱を吸収する過程であり、周囲を暖めるのではなく冷やす。',
