    explanation: '雲粒の捕捉効率は雲粒・雨粒の相対的な大きさに依存し、極小さい雲粒は気流に追従して衝突を避けやすい一方、ある程度の大きさを持つ雲粒は慣性により気流から外れて衝突しやすくなる。この捕捉効率の粒径依存性が、暖かい雨過程における雨粒成長の効率を左右する重要な要素である。\n\n捕捉効率は雲粒と雨粒の半径比が小さすぎても大きすぎても下がり、ある比のときに最大となる。半径20 μm 程度以上の雲粒が存在すると効率よく併合が進むため、大きな凝結核の有無が降水効率を左右する。\n\n【図解】捕捉効率と粒径\n　雲粒の大きさ｜気流への追従｜捕捉効率\n　極めて小さい｜気流に沿って回避｜低い\n　中程度（20 μm 前後）｜慣性で気流から外れる｜高い\n　雨粒に近い｜落下速度差が小さい｜低下する\n　⇒ 落下速度差と慣性の両方が効くため、最適な粒径比が存在する\n　⚠ 「雲粒が小さいほど捕捉効率が高い」は誤り。小さすぎると回避されてしまう。',
