    question: '過冷却水滴の存在と航空機の着氷現象に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '雲の中には0 °C未満でも凍結せずに液体のまま存在する過冷却水滴がしばしば見られ、これに航空機の機体が接触すると急激に凍結し、着氷（機体表面への氷の付着）を引き起こすことがある。', explanation: '正しい。水は0 °C未満でも凝固核がなければ容易には凍結せず、雲中では−10〜−20 °C程度、時にはそれ以下の温度でも液体のまま存在する（過冷却水滴）。これが機体などの固体表面に接触すると衝撃により急速に凍結し、着氷を引き起こす。' },
      { key: 'B', text: '過冷却水滴は0 °Cに達すると同時に必ず全て凍結する。', explanation: '誤り。過冷却水滴は凝固核が乏しいため0 °C未満でも直ちには凍結せず、液体のまま存在し続けることができる（準安定状態）。' },
      { key: 'C', text: '着氷現象は気温が0 °C以上の場合にのみ発生する。', explanation: '誤り。着氷は主に0 °C未満の過冷却水滴が存在する雲域で発生する現象であり、気温が0 °C以上では通常発生しない。' },
      { key: 'D', text: '過冷却水滴は成層圏でのみ観測される現象であり、対流圏の雲には存在しない。', explanation: '誤り。過冷却水滴は対流圏内の雲（積乱雲や層状の氷晶・水滴混合雲など）で広く観測される現象であり、成層圏に限られたものではない。' },
    ],
    correctKey: 'A',
    explanation: '過冷却水滴は0 °C未満でも凝固核が乏しいために液体のまま準安定的に存在でき、雲中では−10〜−20 °C程度まで広く見られる。この過冷却水滴が航空機などの固体表面に接触すると衝撃的に凍結し着氷を引き起こすため、雲頂高度や気温分布から着氷の危険性を評価することは航空気象で重要な業務の一つである。\n\n着氷は過冷却水滴が豊富な雲の中を飛行するときに起こり、−10〜−20 ℃の混合雲でとくに危険度が高い。翼形状が変わって失速速度が上がるほか、ピトー管の閉塞など計器の異常も招くため、着氷の予測は航空気象の重要業務である。\n\n【図解】着氷の危険度と気温\n　気温帯｜過冷却水滴｜着氷の危険\n　0〜−10 ℃｜非常に多い｜高い（雨氷になりやすい）\n　−10〜−20 ℃｜氷晶と共存｜高い（樹氷になりやすい）\n　−20 ℃以下｜少ない｜低下する\n　⇒ 過冷却水滴が多い温度帯ほど着氷の危険が高い\n　⚠ 着氷は0 ℃未満の環境で起こる現象で、0 ℃以上では発生しない。',
    difficulty: 'standard',
    examYear: '令和4年',
