    correctKey: 'A',
    explanation: '雹は積乱雲内の強い上昇流に支えられながら過冷却水滴を繰り返し捕捉して成長する。水滴の供給速度に対して凍結が速い場合は乾燥成長（不透明層）、供給過多で凍結が追いつかない場合は湿潤成長（透明層）となり、これらが交互に起こることで雹の断面に見られる年輪状の層構造が形成される。\n\n雹が大きく成長するには、上昇流が強くて落下を支え続けられること、過冷却水が豊富であることが必要である。スーパーセルのように上昇流が持続する積乱雲では、直径5 cmを超える大粒の雹が降ることもある。\n\n【図解】雹の成長様式\n　様式｜水滴の供給｜できる氷の層\n　乾燥成長｜少なく即座に凍結｜気泡を含む不透明な層\n　湿潤成長｜多く凍結が追いつかない｜気泡の少ない透明な層\n　交互に繰り返す｜上下運動による｜年輪状の層構造\n　⇒ 層構造は雹が雲内で何度も上下したことの記録である\n　⚠ 雹の成長には過冷却水滴の捕捉が不可欠で、昇華だけでは大きくならない。',
