    choices: [
      { key: 'A', text: '均質核生成は水滴自身の分子だけで氷の結晶構造が自発的に形成される過程で、−35 °C以下といった非常に低い温度でなければ起こりにくいのに対し、不均質核生成は氷晶核となる微粒子の表面を利用するため、より高い温度（−10〜−20 °C程度）でも氷晶が生成されうる。', explanation: '正しい。均質核生成は外部の核を介さず水滴自身の分子の揺らぎのみで氷の結晶格子が形成される過程であり、非常に低温（およそ−35 °C以下）でないと起こりにくい。一方、鉱物質のダストなどの氷晶核が存在すると、その表面を鋳型として、より高温（−10〜−20 °C程度）でも氷晶が形成されやすくなる（不均質核生成）。' },
      { key: 'B', text: '均質核生成は0 °C付近の比較的高い気温で最も起こりやすい過程である。', explanation: '誤り。均質核生成が卓越するのは−35 °C以下といった非常に低温の環境であり、0 °C付近では起こりにくい。' },
      { key: 'C', text: '不均質核生成には氷晶核となる微粒子は不要であり、水滴のみで生成が進む。', explanation: '誤り。不均質核生成はまさに氷晶核となる外部の微粒子（鉱物質のダストなど）の表面を利用して進む過程であり、微粒子は本質的に必要な要素である。' },
      { key: 'D', text: '不均質核生成は均質核生成よりも氷晶生成に必要な過冷却度（凍結に必要な低温の程度）が大きい。', explanation: '誤り。不均質核生成は氷晶核の助けを借りることで、均質核生成よりも高い温度（＝小さい過冷却度）で氷晶が生成されるため、必要な過冷却度は均質核生成よりも小さい。' },
    ],
