    explanation: '均質核生成は水滴分子のみで氷結晶が自発的に形成される過程で−35 °C以下という極低温を要するのに対し、不均質核生成は鉱物質ダストなどの氷晶核（IN）の表面を鋳型として、より高い温度（−10〜−20 °C程度）でも氷晶形成を可能にする。大気中の氷晶の多くは不均質核生成によって形成されると考えられている。\n\n不均質核生成に働く氷晶核には鉱物粒子や火山灰、バクテリア由来の粒子などがあり、その数は雲凝結核に比べて桁違いに少ない。このため雲の中では氷晶が少数で過冷却水滴が多数という状態が生じ、氷晶過程が効率よく働く。\n\n【図解】氷晶の核生成\n　様式｜必要な温度｜必要なもの\n　均質核生成｜約−35 ℃以下｜水滴の分子のみ\n　不均質核生成｜−10〜−20 ℃程度｜氷晶核（鉱物粒子など）\n　氷晶核の数｜雲凝結核より非常に少ない｜氷晶が少数になる理由\n　⇒ 大気中の氷晶の多くは不均質核生成で作られる\n　⚠ 不均質核生成のほうが高い温度で起こる。過冷却度が大きいとするのは逆。',
