    question: '暖かい雨（温暖雨、衝突・併合過程による降水）の生成効率と雲の厚さの関係に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '雲の鉛直方向の厚さが大きいほど、雲粒が上昇流中に長く留まり衝突・併合を繰り返す時間や距離が長くなるため、降水粒子まで成長しやすく、暖かい雨の生成効率は高まる傾向がある。', explanation: '正しい。衝突・併合過程による雲粒の成長は、雲粒同士が雲内で相対的に落下・衝突する機会の積み重ねであるため、雲の厚さ（鉛直方向の広がり）が大きいほど成長の機会が増え、降水として成長しやすくなる。熱帯域の厚い暖かい雲でこの過程が効率的に働く理由の一つである。' },
      { key: 'B', text: '雲の厚さは暖かい雨の生成効率に一切影響を与えない。', explanation: '誤り。雲の厚さは雲粒が衝突・併合を繰り返す機会（時間・距離）を左右するため、暖かい雨の生成効率に直接的に影響する。' },
      { key: 'C', text: '雲が薄いほど暖かい雨の生成効率は高くなる。', explanation: '誤り。雲が薄いと雲粒が衝突・併合を繰り返す機会が少なくなるため、一般に暖かい雨の生成効率は低くなる。' },
      { key: 'D', text: '暖かい雨過程は雲の厚さよりも気温の絶対値のみによって効率が決まる。', explanation: '誤り。暖かい雨過程（衝突・併合）の効率は主に雲粒の粒径分布や上昇流の強さ、雲の厚さ（滞在時間）に依存し、気温の絶対値のみで単純に決まるものではない。' },
    ],
    correctKey: 'A',
    explanation: '暖かい雨（衝突・併合過程）は雲粒同士が雲内で繰り返し衝突・合体することで成長する過程であり、雲の鉛直方向の厚さが大きいほど雲粒が成長する時間的・空間的余地が増え、降水粒子への成長効率が高まる。これは熱帯の厚い積雲で温暖雨過程が効率的に働く理由の一つである。\n\n併合が進むには雲粒が上昇流に支えられながら長い距離を落下する必要があるため、厚い雲ほど有利になる。目安として雲の厚さが2 km を超えると暖かい雨が降りやすくなり、海洋上の清浄な大気ではさらに効率が高まる。\n\n【図解】暖かい雨の効率を決める条件\n　条件｜降水効率が高い場合｜低い場合\n　雲の厚さ｜厚い（2 km 以上）｜薄い\n　雲粒の大きさの幅｜広い｜そろっている\n　凝結核｜少なく大きい｜多く小さい\n　⇒ 雲が厚いほど衝突・併合を繰り返す時間と距離が稼げる\n　⚠ 「雲が薄いほど効率が高い」は逆。厚い雲ほど降水粒子まで成長しやすい。',
