    choices: [
      { key: 'A', text: 'ハレット・モスロップ過程は、氷あられ（グラウペル）が過冷却水滴を捕捉して凍結する際、氷の微小な破片（スプリンター）が飛び散ることで氷晶の数が急激に増える現象であり、およそ−3〜−8 °C程度の限られた温度帯で活発とされる。', explanation: '正しい。氷あられが比較的大きな過冷却水滴を捕捉して凍結する際、凍結の過程で氷の微小な破片が周囲に飛散し、これが新たな氷晶核として働くことで氷晶の数が急激に（元の氷晶核の数から予想される以上に）増加する現象がハレット・モスロップ過程であり、およそ−3〜−8 °Cの限られた温度帯で最も活発に起こるとされる。' },
      { key: 'B', text: 'ハレット・モスロップ過程はあらゆる温度帯で一様に活発に起こる現象である。', explanation: '誤り。ハレット・モスロップ過程はおよそ−3〜−8 °Cという限られた温度帯で特に活発になるとされ、あらゆる温度で一様に起こるわけではない。' },
      { key: 'C', text: 'ハレット・モスロップ過程は水蒸気の直接的な昇華のみによって氷晶数が増える現象である。', explanation: '誤り。ハレット・モスロップ過程は氷あられによる過冷却水滴の捕捉・凍結に伴う破片の飛散が本質であり、水蒸気の直接昇華による氷晶生成とは異なる機構である。' },
      { key: 'D', text: 'ハレット・モスロップ過程によって増殖した氷晶は、その後の雲の発達には影響を与えない。', explanation: '誤り。この過程で急増した氷晶は雲内の氷粒子数を増大させ、その後の降水粒子の成長や雲の電荷分離（雷の発生）にも影響を与えると考えられている。' },
    ],
    correctKey: 'A',
    explanation: 'ハレット・モスロップ過程は氷あられが過冷却水滴を捕捉・凍結する際に生じる氷の微小破片（スプリンター）の飛散により、氷晶数が急激に増殖する現象で、およそ−3〜−8 °Cの限られた温度帯で活発に起こる。この二次的な氷晶増殖過程は積乱雲内の氷粒子数の急増を説明する重要な機構として知られている。\n\n氷晶核の数は非常に少ないのに、雲の中の氷粒子数が氷晶核の数を桁違いに上回ることがあり、その説明としてこの二次氷晶生成が重要視される。条件は−3〜−8 ℃で、直径25 μm 以上の過冷却水滴が存在することとされる。\n\n【図解】ハレット・モスロップ過程\n　項目｜条件｜結果\n　温度帯｜約−3〜−8 ℃｜この範囲でのみ活発\n　必要な粒子｜氷あられと過冷却水滴｜捕捉と凍結\n　生じるもの｜氷の微小破片｜氷晶数が急増\n　⇒ 氷晶核の数を大きく超える氷粒子数を説明できる\n　⚠ この過程は限られた温度帯でのみ働き、あらゆる温度で一様に起こるのではない。',
