    question: '雪結晶の形態（樹枝状、板状、針状など）が気温と過飽和度によって変化することに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '雪結晶の形態は、成長時の気温と水蒸気の過飽和度の組み合わせによって系統的に変化することが知られており、例えばおよそ−15 °C付近で過飽和度が高い場合には樹枝状の結晶が成長しやすいとされる。', explanation: '正しい。中谷宇吉郎らの研究に代表されるように、雪結晶の形態（板状・柱状・針状・樹枝状など）は成長時の気温と過飽和度の組み合わせによって系統的に変化することが実験的に明らかにされており、およそ−15 °C付近の高過飽和度条件下では複雑な樹枝状結晶が成長しやすいことが知られている。' },
      { key: 'B', text: '雪結晶の形態は気温や過飽和度によらず、常に同じ六角形の板状となる。', explanation: '誤り。雪結晶の形態は気温・過飽和度に応じて板状・柱状・針状・樹枝状など多様な形態をとることが知られている。' },
      { key: 'C', text: '雪結晶の形態は成長時の気圧のみによって一意に決まり、気温は関係しない。', explanation: '誤り。雪結晶の形態を左右する主な要因は成長時の気温と水蒸気の過飽和度であり、気圧そのものが主要因ではない。' },
      { key: 'D', text: '樹枝状結晶は0 °C付近の比較的高い気温で最も成長しやすい。', explanation: '誤り。樹枝状結晶が成長しやすいとされるのはおよそ−15 °C付近の温度帯であり、0 °C付近ではない。' },
    ],
    correctKey: 'A',
    explanation: '雪結晶の形態は成長時の気温と水蒸気の過飽和度の組み合わせによって系統的に変化することが実験的研究（中谷ダイアグラムなど）によって明らかにされており、およそ−15 °C付近の高過飽和度環境で複雑な樹枝状結晶が発達しやすいことが知られている。\n\n中谷宇吉郎が明らかにしたこの対応関係により、雪結晶の形から上空の気温と湿度を推定でき、雪は天から送られた手紙と表現される。−15 ℃付近の高過飽和度では枝が複雑に伸びた樹枝状結晶が発達する。\n\n【図解】気温と雪結晶の形\n　気温｜過飽和度が高いとき｜形の傾向\n　0〜−4 ℃｜針状｜細長い\n　−4〜−10 ℃｜角柱状｜柱のような形\n　−10〜−22 ℃｜樹枝状｜−15 ℃付近で最も複雑\n　−22 ℃以下｜角板状｜単純な板状\n　⇒ 結晶の形から成長時の気温と湿度を推定できる\n　⚠ 樹枝状結晶ができるのは−15 ℃付近。0 ℃付近で最も発達するのではない。',
    difficulty: 'standard',
