    explanation: '氷あられは初期段階の小さな霰状氷粒子（直径5 mm未満程度、密度が低い）であるのに対し、雹は積乱雲内の強い上昇流の中で過冷却水滴の付着・凍結を繰り返して大きく成長した氷塊（しばしば直径数cm以上、密度が高く層構造を持つ）であり、両者は成長過程と規模の点で区別される。\n\n気象観測では、直径5 mm 未満のものを霰（あられ）、5 mm 以上のものを雹として区別する。雹は強い上昇流が必要なため主に暖候期の発達した積乱雲で降り、冬季は霰や雪あられが中心となる。\n\n【図解】固体降水の区分\n　名称｜直径｜特徴\n　雪あられ｜5 mm 未満｜白く不透明でもろい\n　氷あられ｜5 mm 未満｜半透明でやや硬い\n　雹｜5 mm 以上｜層構造をもち硬い\n　⇒ 雹は強い上昇流の中で何度も成長を繰り返した結果である\n　⚠ 氷あられが雹より大きいとするのは逆。また雹は暖候期に多い。',
