    explanation: '人工降雨（クラウドシーディング）はヨウ化銀（氷晶核として作用）や吸湿性粒子（凝結核として作用）を既存の雲中に散布し、自然の氷晶過程や衝突・併合過程を人為的に促進して降水を増やそうとする技術である。効果は雲の状態に大きく依存し、渇水対策などの目的で研究・実施されている。\n\nヨウ化銀は結晶構造が氷に似ているため氷晶核として働き、氷晶過程を促進する。ドライアイスは局所的に急冷して氷晶を作る。いずれもすでに雲があり水蒸気が十分あることが前提で、晴天から雨を作ることはできない。\n\n【図解】人工降雨に使う物質\n　物質｜働き｜対象とする過程\n　ヨウ化銀｜氷晶核となる｜氷晶過程\n　ドライアイス｜急冷して氷晶を作る｜氷晶過程\n　吸湿性の塩粒子｜大きな凝結核となる｜衝突併合過程\n　⇒ 自然の降水過程を後押しする技術であり、無から雨を作るのではない\n　⚠ ヨウ化銀は雲を消すためではなく、氷晶を作って降水を促すために撒く。',
