    subjectName: '予報業務に関する一般知識',
    question: 'ケルビンの循環定理に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'ケルビンの循環定理は、非粘性・順圧（密度が気圧のみの関数）で保存力のみが働く流体において、流体に沿って運ばれる閉曲線に沿った循環（速度の接線成分の線積分）が時間的に保存されることを示す定理である。', explanation: '正しい。ケルビンの循環定理は理想流体（非粘性・順圧）において、物質的に同じ流体粒子から成る閉曲線に沿った循環Γ＝∮v・dlが時間変化しないことを主張する定理であり、渦度と循環の関係（ストークスの定理）を通じて大気の渦度保存則の理論的基礎となる。' },
      { key: 'B', text: 'ケルビンの循環定理は粘性が強く働く流体でのみ成立する定理である。', explanation: '誤り。ケルビンの循環定理は非粘性（粘性の効果を無視できる）流体を前提とした定理であり、粘性が強く働く場合には循環は保存されず定理は成立しない。' },
      { key: 'C', text: 'ケルビンの循環定理によれば、傾圧大気（密度が気圧と温度の両方に依存する大気）でも循環は常に厳密に保存される。', explanation: '誤り。傾圧大気（密度面と気圧面が交差する大気）では圧力と密度の勾配が非平行になることで循環を生み出すトルク（傾圧項）が働くため、循環は一般に保存されない。循環定理が厳密に成り立つのは順圧流体の場合である。' },
      { key: 'D', text: 'ケルビンの循環定理は大気の渦度保存則とは無関係な、全く独立した理論である。', explanation: '誤り。ケルビンの循環定理はストークスの定理を通じて渦度の面積分（＝循環）の保存を意味し、大気力学における渦度保存則・渦位保存則の理論的基礎となっている。' },
    ],
    correctKey: 'A',
    explanation: 'ケルビンの循環定理は非粘性・順圧流体において、流体粒子から成る閉曲線に沿った循環が時間的に保存されることを示す。傾圧大気では傾圧項（圧力・密度勾配の非平行性によるトルク）により循環が変化しうるが、この定理は大気の渦度・渦位保存則を理解する上での基礎理論として位置づけられる。\n\n順圧流体では等圧面と等密度面が平行なので圧力による回転のトルクが生じず循環が保存されるが、傾圧流体では両者が交わるため傾圧項が働いて循環が変化する。海陸風や前線の循環はこの傾圧項によって生み出される。\n\n【図解】循環定理の成立条件\n　条件｜循環の扱い｜例\n　非粘性・順圧・保存力｜保存される｜理想化された流体\n　傾圧（等圧面と等密度面が交差）｜傾圧項で変化｜海陸風・前線循環\n　粘性あり｜摩擦で減衰｜境界層内\n　⇒ 傾圧項こそが大気に新たな循環を生み出す源である\n　⚠ 傾圧大気でも循環が厳密に保存されるとするのは誤り。傾圧項が効く。',
