    subjectName: '予報業務に関する一般知識',
    question: 'リチャードソン数と乱流の発生の関係に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'リチャードソン数は静的安定度（浮力による乱流抑制効果）と鉛直方向の風速シアー（乱流を生成しようとする効果）の比を表す無次元数であり、一般にこの値がおよそ0.25を下回ると流れは力学的に不安定になり乱流が発生しやすくなるとされる。', explanation: '正しい。リチャードソン数 Ri＝(g/θ)(∂θ/∂z)/(∂u/∂z)² は安定度（分子）とシアー（分母）の比であり、Riが小さい（シアーが強い、または安定度が弱い）ほど流れは不安定になりやすい。臨界値としてRi＜0.25（あるいは1）が乱流発生の目安として広く用いられる。' },
      { key: 'B', text: 'リチャードソン数が大きいほど乱流は発生しやすくなる。', explanation: '誤り。リチャードソン数が大きい（安定度が強くシアーが弱い）ほど乱流は発生しにくく、値が小さいほど乱流が発生しやすくなる。' },
      { key: 'C', text: 'リチャードソン数は風速の鉛直シアーのみに依存し、大気の安定度とは無関係な量である。', explanation: '誤り。リチャードソン数の定義には静的安定度（温位の鉛直勾配）と風速シアーの両方が含まれており、両者の比として定義される量である。' },
      { key: 'D', text: 'リチャードソン数が負の値をとることは物理的にありえない。', explanation: '誤り。大気が絶対不安定（温位が高度とともに減少）な場合、リチャードソン数の分子が負となるためRiは負の値をとりうる。この場合、シアーの有無にかかわらず対流が発生しやすい状態を意味する。' },
    ],
    correctKey: 'A',
    explanation: 'リチャードソン数Riは静的安定度と鉛直シアーの比を表す無次元数で、Ri＜0.25（臨界リチャードソン数）程度になると流れは力学的に不安定となり、ケルビン・ヘルムホルツ波の発生などを通じて乱流が生じやすくなる。晴天乱気流（CAT）の予測にもこの考え方が応用される。\n\nリチャードソン数は Ri＝N²/(∂U/∂z)² の形をとり、分子が浮力による抑制、分母がシアーによる乱流生成を表す。逆転層のように非常に安定な層でも、その上下で風速差が大きければ乱流が発生し、晴天乱気流の原因となる。\n\n【図解】リチャードソン数と流れの状態\n　Ri の値｜流れの状態｜乱流\n　0.25 より大きい｜安定｜乱流は発達しにくい\n　0.25 付近以下｜力学的に不安定｜ケルビン・ヘルムホルツ波\n　負｜静的に不安定｜対流が発生\n　⇒ 安定な層でも強いシアーがあれば乱流が生じる\n　⚠ 「Ri が大きいほど乱流が発生しやすい」は逆。大きいほど安定である。',
