    correctKey: 'A',
    explanation: 'ロスビー変形半径（Lr＝NH/f）は回転（コリオリ力）と浮力（静的安定度）の効果が拮抗する特徴的な水平スケールであり、中緯度ではおよそ1000 km程度となる。このスケール程度の擾乱では気圧場・風速場が地衡風調節を通じて同程度に影響し合い、これが温帯低気圧など中緯度総観規模擾乱の代表的な空間スケールにほぼ対応する。\n\n変形半径より大きなスケールの擾乱では風の場が気圧の場に合わせて調節され、逆に小さなスケールでは気圧の場が風の場に合わせて調節される。中緯度の変形半径がおよそ1000 kmであることが、温帯低気圧の大きさを決めている。\n\n【図解】ロスビー変形半径とスケール\n　擾乱のスケール｜地衡風調節の向き｜例\n　変形半径より大きい｜風の場が調節される｜プラネタリー波\n　変形半径程度｜両者が同程度に調節｜温帯低気圧\n　変形半径より小さい｜気圧の場が調節される｜積乱雲\n　⇒ 中緯度の変形半径は約1000 kmで、総観規模擾乱の大きさに対応する\n　⚠ 変形半径は f を含むため緯度で変わる。一定値とするのは誤り。',
