    question: '慣性振動（大気が地衡風から外れて自由に振動する運動）の周期と緯度の関係に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '慣性振動の周期（慣性周期）はコリオリパラメータf＝2Ωsinφに反比例し、緯度φが高いほど周期は短く、赤道に近づくほど周期は長くなり赤道上では無限大となる。', explanation: '正しい。慣性振動の角振動数はコリオリパラメータfに等しく、周期T＝2π/fで与えられるため、fが大きい高緯度ほど周期は短く（例えば緯度45°ではおよそ半日強）、fがゼロに近づく赤道付近では周期は長くなり、赤道上（f=0）では慣性振動そのものが定義できなくなる（周期が無限大に発散する）。' },
      { key: 'B', text: '慣性振動の周期は緯度に関係なく、地球上どこでも同じ値（24時間）をとる。', explanation: '誤り。慣性振動の周期はコリオリパラメータfに反比例するため緯度によって大きく異なり、一定値（24時間）ではない。' },
      { key: 'C', text: '慣性振動の周期は赤道付近で最も短く、極付近で最も長くなる。', explanation: '誤り。関係が逆である。慣性周期は極付近（fが大きい）で最も短く、赤道付近（fがゼロに近い）で最も長くなる（赤道上では発散する）。' },
      { key: 'D', text: '慣性振動は摩擦のある大気境界層内でのみ発生する現象であり、自由大気では発生しない。', explanation: '誤り。慣性振動は地衡風平衡からのずれによって自由大気中でも生じる現象であり、大気境界層に限定されるものではない（ただし境界層では夜間に摩擦の減少によって顕著化する慣性振動が観測されることもある）。' },
    ],
    correctKey: 'A',
    explanation: '慣性振動の周期T＝2π/f（f＝2Ωsinφ）はコリオリパラメータに反比例する。緯度45°付近ではおよそ17時間程度、高緯度ほど短く、赤道に近づくほど長くなり赤道上（f=0）では定義できなくなる。この現象は夜間の下層ジェット（ノクターナルジェット）の形成メカニズムの一つとしても知られる。\n\n慣性振動は気圧傾度力が急に消えた場合などに、コリオリ力だけが働いて空気塊が円を描く運動である。夜間に境界層の摩擦が弱まると下層の風がこの振動を始め、明け方に地衡風より強い夜間下層ジェットを作ることがある。\n\n【図解】緯度と慣性周期\n　緯度｜コリオリパラメータ f｜慣性周期\n　30度｜約0.73×10⁻⁴ s⁻¹｜約24時間\n　45度｜約1.03×10⁻⁴ s⁻¹｜約17時間\n　60度｜約1.26×10⁻⁴ s⁻¹｜約14時間\n　⇒ 高緯度ほど f が大きく、慣性周期は短くなる\n　⚠ 「赤道で最も短い」は逆。赤道では f がゼロで周期が定義できなくなる。',
