    question: '準地衡風オメガ方程式における「渦度移流の高度による変化（差渦度移流）」の役割に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '上層で正渦度移流が強く、それより下層で正渦度移流が弱い（または負渦度移流である）場合、すなわち高度とともに正渦度移流が増加する状況では、その地点付近で上昇流が強制される傾向がある。', explanation: '正しい。準地衡風オメガ方程式の一つの定性的解釈（差渦度移流の考え方）によれば、渦度移流が高度とともに強まる（上層の正渦度移流が下層より大きい）状況は上昇流を強制する。これはトラフ前面（上層で正渦度移流が大きい領域）で地上低気圧の発達に対応する上昇流が生じることの説明としてよく用いられる。' },
      { key: 'B', text: '渦度移流は高度によらず常に一定であり、鉛直流の診断には寄与しない。', explanation: '誤り。準地衡風オメガ方程式では渦度移流の高度変化（差渦度移流）こそが鉛直流を強制する主要な項の一つであり、渦度移流が高度によらず一定であれば鉛直流への寄与はむしろ小さくなる。' },
      { key: 'C', text: '上層の正渦度移流が下層より小さい場合に、その地点付近で上昇流が強制される。', explanation: '誤り。上昇流が強制されるのは上層の正渦度移流が下層より大きい（高度とともに正渦度移流が増加する）場合であり、記述は逆である。' },
      { key: 'D', text: '差渦度移流の考え方は下層の低気圧の動きの予測にのみ用いられ、上昇流の診断には応用できない。', explanation: '誤り。差渦度移流の考え方はまさに準地衡風オメガ方程式に基づく鉛直流（上昇流・下降流）の定性的診断手法として用いられるものであり、天気図解析の実技において広く応用される。' },
    ],
    correctKey: 'A',
    explanation: '準地衡風オメガ方程式の差渦度移流による定性的解釈では、上層の正渦度移流が下層より大きい（高度とともに正渦度移流が増大する）状況で上昇流が強制される。この考え方はトラフ前面での上昇流や地上低気圧の発達を説明する実技上重要な着眼点である。\n\n差渦度移流が上昇流を生むのは、上層で渦度が増える傾向を打ち消すために発散が必要となり、その発散を補う上昇流が下から誘起されるためである。トラフ前面が典型的な場所で、地上低気圧はここで発達する。\n\n【図解】差渦度移流と鉛直流\n　高度による正渦度移流｜生じる鉛直流｜地上への影響\n　上層で強く下層で弱い｜上昇流｜低気圧が発達\n　上層で弱く下層で強い｜下降流｜高気圧が強まる\n　高度によらず一定｜強制なし｜変化なし\n　⇒ 差があること自体が鉛直流を生む要因である\n　⚠ 上層の正渦度移流が下層より小さいときに上昇流とするのは逆である。',
