    correctKey: 'A',
    explanation: '大気境界層内では摩擦により風が地衡風から等圧線を横切る方向（低圧側）にずれるため、低気圧の中心付近では水平収束が生じる。この収束を補うように境界層上端から自由大気へ向かう上昇流（エクマンポンピング）が生じ、自由大気側の上昇流を補強する役割を果たす。\n\nエクマンポンピングによる上昇流は毎秒1 cm 程度と小さいが、低気圧の中心付近で長時間続くため無視できない。逆に高気圧では境界層の吹き出しにより下降流が生じ、これをエクマンサクションと呼ぶ。\n\n【図解】境界層の摩擦と鉛直流\n　地上の気圧配置｜境界層内の風｜境界層上端の鉛直流\n　低気圧｜収束（吹き込み）｜上昇流（エクマンポンピング）\n　高気圧｜発散（吹き出し）｜下降流（エクマンサクション）\n　⇒ 鉛直流の大きさは地上の相対渦度にほぼ比例する\n　⚠ 低気圧の中心で摩擦により発散が生じるとするのは逆。収束するのが正しい。',
    difficulty: 'standard',
    examYear: '令和4年',
