    correctKey: 'A',
    explanation: 'ロスビー波は分散性の波であり、位相速度（波形自体の移動速度）は常に西向き成分を持つのに対し、群速度（エネルギーの伝播速度）は波数に依存し、短波長では東向きになることがある。この性質により、上流で発生した擾乱のエネルギーが下流側に伝わる「ロスビー波列（テレコネクション）」の理解に重要な役割を果たす。\n\n位相速度が西向きなのはβ効果による復元力の結果で、その大きさは波長の2乗に比例する。基本場の西風が強いと短波は流されて東進し、超長波は西進の効果が勝って停滞または西進する。群速度が東向きになることで擾乱のエネルギーが下流へ伝わる。\n\n【図解】ロスビー波の速度\n　項目｜向き｜特徴\n　位相速度（基本場に対して）｜西向き｜波長の2乗に比例\n　超長波の実際の動き｜停滞または西進｜ブロッキング\n　短波の実際の動き｜東進｜温帯低気圧に対応\n　群速度｜東向きになりうる｜下流へエネルギー伝播\n　⇒ 位相速度と群速度が異なることが波列の下流発達を生む\n　⚠ 位相速度が常に東向きとするのは誤り。基本場に対しては西向きである。',
