    question: '順圧大気と傾圧大気の違いに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '順圧大気では気温（密度）が気圧面上で一様であるため地衡風は高度によらず一定（温度風がゼロ）であるのに対し、傾圧大気では気圧面上に水平温度傾度が存在するため、温度風の関係に従って地衡風は高度とともに変化する。', explanation: '正しい。順圧大気は等圧面上の気温（密度）分布が水平方向に一様な仮想的な大気であり、この場合は温度風（上下の地衡風の差）がゼロとなるため地衡風は高度によらず一定となる。実際の大気は等圧面上に水平温度傾度を持つ傾圧大気であり、温度風の関係から地衡風が高度とともに変化する（典型的には対流圏界面付近でジェット気流として強まる）。' },
      { key: 'B', text: '順圧大気では地衡風は高度とともに大きく変化する。', explanation: '誤り。順圧大気では等圧面上の気温が一様（水平温度傾度がゼロ）であるため温度風がゼロとなり、地衡風は高度によらず一定となる。高度とともに大きく変化するのは傾圧大気の特徴である。' },
      { key: 'C', text: '実際の中緯度の大気は理想的な順圧大気として扱うのが最も正確である。', explanation: '誤り。実際の中緯度大気は南北に大きな温度傾度を持つ傾圧大気であり、順圧大気という仮定は理論を単純化するための近似（例えば順圧不安定の理論など）にすぎない。' },
      { key: 'D', text: '傾圧大気では温度風は常にゼロとなる。', explanation: '誤り。傾圧大気ではまさに水平温度傾度が存在するために温度風がゼロでない値をとり、これが地衡風の高度変化（鉛直シアー）を生む。' },
    ],
    correctKey: 'A',
