    question: '同じ気圧傾度力のもとで比較した場合の地衡風と傾度風（曲線状の等圧線に沿う風）の風速の違いに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '北半球の低気圧性曲率を持つ等圧線に沿う傾度風は、同じ気圧傾度力に対応する地衡風よりも風速が小さくなり、逆に高気圧性曲率を持つ場合の傾度風は地衡風よりも風速が大きくなる。', explanation: '正しい。傾度風の釣り合いの式では低気圧性の曲率の場合、遠心力が気圧傾度力と同じ向き（外向き）に働くため、コリオリ力単独でつり合うのに必要な風速は地衡風より小さくてすむ。逆に高気圧性の曲率では遠心力が気圧傾度力と逆向き（外向き、気圧傾度力は内向き）に働くため、同じ気圧傾度力に対してより大きな風速が必要となる。' },
      { key: 'B', text: '低気圧性曲率の傾度風は地衡風より風速が大きくなり、高気圧性曲率の傾度風は地衡風より風速が小さくなる。', explanation: '誤り。関係が逆である。低気圧性曲率では傾度風は地衡風より風速が小さく、高気圧性曲率では地衡風より風速が大きくなる。' },
      { key: 'C', text: '地衡風と傾度風の風速は等圧線の曲率によらず常に完全に一致する。', explanation: '誤り。地衡風は等圧線が直線であることを仮定した近似風であり、実際の曲線状の等圧線に沿う傾度風とは曲率（遠心力）の効果の分だけ風速が異なる。' },
      { key: 'D', text: '傾度風の風速は等圧線の曲率半径が小さいほど地衡風との差が小さくなる。', explanation: '誤り。曲率半径が小さいほど遠心力の効果（v²/r）が相対的に大きくなるため、地衡風との差はむしろ大きくなる。曲率半径が非常に大きい（直線に近い）場合に地衡風との差は小さくなる。' },
    ],
    correctKey: 'A',
    explanation: '傾度風は気圧傾度力・コリオリ力・遠心力の三力の釣り合いで決まる。低気圧性曲率では遠心力が気圧傾度力を助ける向きに働くため地衡風より小さい風速で釣り合い、高気圧性曲率では遠心力が気圧傾度力に逆らう向きに働くため地衡風より大きい風速が必要となる（この非対称性から高気圧に極端に強い風は生じにくいことが説明される）。\n\n曲率半径が小さいほど遠心力の効果が大きくなり、地衡風との差が広がる。高気圧では風速を上げないと釣り合わないが、気圧傾度が大きすぎると解が存在しなくなるため、高気圧の中心付近の気圧傾度は自然に緩やかになる。\n\n【図解】曲率と傾度風\n　曲率｜遠心力の向き｜地衡風との比較\n　低気圧性｜外向き（コリオリ力と同じ側）｜風速が小さい\n　高気圧性｜外向き（気圧傾度力と同じ側）｜風速が大きい\n　曲率半径が小さい｜遠心力が大きい｜差が広がる\n　⇒ 高気圧の中心付近で極端な強風が生じにくい理由になる\n　⚠ 曲率半径が小さいほど差が小さくなるとするのは逆である。',
