    correctKey: 'A',
    explanation: '渦度方程式には移流項・伸長項（水平収束で渦度増大）・傾き項（水平渦度が鉛直渦度へ変換）・ソレノイド項（傾圧効果）などが含まれる。特に伸長項は積乱雲下での収束による渦度増幅（竜巻の形成の一因）、傾き項はスーパーセルのメソサイクロン形成に関わる重要な項として、メソスケール現象の力学の理解に用いられる。\n\n伸長項は収束によって渦柱が細く引き伸ばされて回転が速まる効果で、竜巻やメソサイクロンの強化に効く。傾き項は水平軸の渦が上昇流によって立ち上がる効果で、スーパーセルの回転の起源となる。\n\n【図解】渦度方程式の主な項\n　項｜働き｜代表的な現象\n　移流項｜渦度を運ぶ｜トラフの東進\n　伸長項｜収束で渦度を増大｜竜巻の強化\n　傾き項｜水平渦度を鉛直へ｜メソサイクロンの形成\n　ソレノイド項｜傾圧効果｜海陸風や前線循環\n　⇒ 収束すなわち発散が負のとき絶対渦度は増大する\n　⚠ 「水平発散が正のときに渦度が増える」は逆。収束のときに増える。',
