    choices: [
      { key: 'A', text: 'ある高度の気層で水平方向の風が収束している（水平発散が負である）場合、質量保存則を満たすためにその気層からの鉛直方向への質量の流出（すなわち上方または下方への鉛直流）が生じる。', explanation: '正しい。連続の式（質量保存則）∂ρ/∂t+∇・(ρv)=0を単純化すると、水平発散と鉛直方向の質量フラックスの変化は互いに補い合う関係にあり、水平収束（水平発散が負）が生じている層では、その分の質量を鉛直方向に逃がす必要があり、鉛直流（多くの場合は上向き）が誘起される。' },
      { key: 'B', text: '水平収束が生じている層では、質量保存則により必ず鉛直流はゼロとなる。', explanation: '誤り。水平収束が生じている場合、その質量の余剰分を解消するために鉛直方向への質量輸送（鉛直流）が必要となり、鉛直流がゼロになるわけではない。' },
      { key: 'C', text: '水平発散と鉛直流の間には物理的な関係は存在しない。', explanation: '誤り。水平発散（収束）と鉛直流は質量保存則（連続の式）を通じて密接に関係しており、気象学における鉛直流診断の基本的な考え方の一つである。' },
      { key: 'D', text: '地上付近で水平収束が生じている場合、通常はその上空で下降流が卓越する。', explanation: '誤り。地上付近の水平収束（低気圧の中心付近など）は通常、その上空で上昇流を伴う（低気圧＝収束・上昇流、高気圧＝発散・下降流という基本的な対応関係）。' },
    ],
    correctKey: 'A',
    explanation: '質量保存則（連続の式）により、ある層で水平収束（発散が負）が生じると、その質量の余剰を解消するために鉛直方向への質量輸送（鉛直流）が誘起される。地上付近の収束は上昇流を、対流圏上層の発散は地上の低気圧発達に対応する上昇流を強めるというように、この関係は天気図解析における鉛直流の定性的診断の基礎となる。\n\n収束や発散は必ず鉛直流と結びつく。地上付近の収束は上昇流を、上層の発散は下からの上昇流を生む。地上の収束と上層の発散が上下で重なるとき、上昇流は最も強くなり低気圧が発達する。\n\n【図解】収束発散と鉛直流の対応\n　高度｜水平の場｜鉛直流\n　地上付近｜収束｜上昇流\n　地上付近｜発散｜下降流\n　上層｜発散｜上昇流を誘起\n　上層｜収束｜下降流を誘起\n　⇒ 下層収束と上層発散が重なる場所で上昇流が最大になる\n　⚠ 「地上で収束していれば上空は下降流」は誤り。上昇流が対応する。',
    difficulty: 'standard',
