    choices: [
      { key: 'A', text: '500 hPaの地衡風は850 hPaの地衡風（南西風10 m/s）に温度風（西風20 m/s相当）を加えたベクトルとなり、850 hPaよりも西寄りの成分が強まった、より強い風（合成風速はおよそ30 m/s未満、風向はより西寄り）になると考えられる。', explanation: '正しい。温度風の関係は上層の地衡風＝下層の地衡風＋温度風（ベクトル）で表される。中緯度で北ほど寒冷な典型的な状況では温度風は西風成分として働くため、下層の南西風に西風成分の温度風を加えると、上層ではより西寄りの成分が強まった風となる（単純なベクトル和のため合成風速は10+20=30 m/sより小さくなるのが一般的）。' },
      { key: 'B', text: '温度風の関係から、上層の地衡風は下層の地衡風より必ず弱くなる。', explanation: '誤り。温度風はベクトル量であり、下層の地衡風に加算される形で働くため、通常（中緯度の典型的な南北温度傾度のもとでは）上層の地衡風は下層よりも強くなる（弱くなるとは限らない）。' },
      { key: 'C', text: '温度風は下層の地衡風の風速を単純に2倍にする効果を持つ。', explanation: '誤り。温度風は下層の地衡風とは独立に南北温度傾度から計算されるベクトル量であり、下層の地衡風を「2倍にする」というような単純な倍率関係にあるわけではない。' },
      { key: 'D', text: '温度風の関係は風向には影響を与えず、風速の大きさのみを変化させる。', explanation: '誤り。温度風はベクトル量として下層の地衡風に加算されるため、風速だけでなく風向にも影響を与える（本問では西風成分が加わることで風向がより西寄りに変化する）。' },
    ],
    correctKey: 'A',
    explanation: '温度風の関係は「上層の地衡風＝下層の地衡風＋温度風」というベクトル和で表される。中緯度の典型的な南北温度傾度（北ほど寒冷）のもとでは温度風は西風成分として働くため、下層の地衡風に西風成分を加えることで上層ではより西寄りの成分を持つ強い風（ジェット気流）が形成される。\n\n温度風はベクトル差なので、上層の風は下層の風に温度風ベクトルを足したものになる。中緯度では北ほど寒いため温度風は西風成分をもち、上層ほど西寄りで強い風になる。これがジェット気流ができる理由である。\n\n【図解】本問のベクトル計算\n　高度｜風｜内訳\n　850 hPa｜南西風10 m/s｜下層の地衡風\n　温度風｜西風20 m/s｜層の温度傾度による\n　500 hPa｜西寄りで強い風｜両者のベクトル和\n　⇒ 上層の地衡風は下層の地衡風と温度風の和で決まる\n　⚠ 温度風は風向も変える。風速だけを変えるとするのは誤り。',
