    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '偏西風の蛇行とブロッキング高気圧に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '偏西風の蛇行が大きくなり、通常西から東へ移動するはずの高気圧が特定の場所に長期間（数日〜数週間）停滞する現象をブロッキング高気圧といい、この間は下流側の低気圧の進行が妨げられ天候が同じ状態で持続しやすくなる。', explanation: '正しい。ブロッキング高気圧は偏西風の蛇行（波打ち）が非常に大きくなった結果、高気圧が移動性を失って特定の場所にとどまり続ける現象で、その名の通り西からの低気圧の進行を「ブロック（阻止）」する働きがあり、猛暑・寒波・長雨など天候の同じ状態の持続に関与する。' },
      { key: 'B', text: 'ブロッキング高気圧は常に高速で東進する高気圧である。', explanation: '誤り。ブロッキング高気圧の最大の特徴はむしろ移動速度が非常に遅い、あるいはほとんど停滞することであり、高速で東進する通常の移動性高気圧とは対照的な現象である。' },
      { key: 'C', text: 'ブロッキング高気圧が形成されると、下流側の低気圧の移動はむしろ促進される。', explanation: '誤り。ブロッキング高気圧はまさに下流側の低気圧などの擾乱の東進を妨げる（せき止める）働きを持ち、その名前の由来もそこにある。' },
      { key: 'D', text: '偏西風の蛇行の大きさは常に一定であり、季節や年によって変化しない。', explanation: '誤り。偏西風の蛇行の大きさ（振幅）は季節・年々変動が大きく、蛇行が特に大きくなった状況でブロッキング高気圧が形成されやすくなる。' },
    ],
    correctKey: 'A',
    explanation: '偏西風の蛇行が大きくなると、高気圧が本来の移動性を失って特定の場所に長期間停滞するブロッキング高気圧が形成されることがある。ブロッキングは下流側の低気圧・前線の進行を妨げるため、その持続期間中は猛暑・寒波・大雨などの偏った天候が長引く要因となる。\n\nブロッキングの型には、高気圧の南に切離低気圧が並ぶダブルブロッキング（オメガ型）や、南北に高低気圧が重なる双極型がある。いったん形成されると1週間以上持続することもあり、猛暑や長雨、寒波の主因となる。\n\n【図解】ブロッキングの影響\n　項目｜内容｜結果\n　偏西風｜大きく蛇行し停滞｜移動性の擾乱が進めない\n　高気圧｜同じ場所に居座る｜数日から数週間\n　下流側｜低気圧の進行が妨げられる｜天候が偏り持続\n　⇒ 超長波の停滞が異常天候を長引かせる仕組みになる\n　⚠ 「下流側の低気圧の移動が促進される」は逆。妨げられて停滞する。',
