    question: '北大西洋振動（NAO：North Atlantic Oscillation）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'NAOはアイスランド低気圧とアゾレス高気圧の気圧の強弱がシーソーのように変動する現象であり、正の位相（両者の気圧差が大きい）のときは北大西洋上の偏西風が強まり、ヨーロッパでは温暖・多雨傾向になりやすい。', explanation: '正しい。NAOはアイスランド付近の低気圧とアゾレス諸島付近の高気圧の気圧偏差のシーソー的な変動を表す指数で、正の位相では両者の気圧差が大きくなり北大西洋を横切る偏西風が強化される。これによりヨーロッパには温暖で湿った空気が運ばれやすくなり温暖・多雨傾向となる。' },
      { key: 'B', text: 'NAOは太平洋の海面水温の変動を表す指数であり、大西洋とは無関係である。', explanation: '誤り。NAOはその名の通り北大西洋域の気圧変動（アイスランド低気圧とアゾレス高気圧のシーソー現象）を表す指数であり、太平洋の海面水温変動（PDOなど）とは異なる現象である。' },
      { key: 'C', text: 'NAOが正の位相のとき、ヨーロッパは寒冷で乾燥した気候になる傾向がある。', explanation: '誤り。NAOが正の位相のときは偏西風が強化され、大西洋からの温暖で湿った空気がヨーロッパに運ばれやすくなるため、むしろ温暖・多雨傾向になりやすい。' },
      { key: 'D', text: 'NAOはエルニーニョ現象と全く同一の現象であり、区別する必要はない。', explanation: '誤り。NAOは北大西洋域の気圧変動、エルニーニョは熱帯太平洋の海面水温変動という、異なる海域・異なるメカニズムに基づく現象であり、明確に区別される。' },
    ],
    correctKey: 'A',
    explanation: 'NAOはアイスランド低気圧とアゾレス高気圧の気圧のシーソー的な変動を表す指数で、正の位相では両者の気圧差が拡大し北大西洋の偏西風が強化され、ヨーロッパに温暖多雨をもたらしやすい。負の位相では逆に偏西風が弱まり、寒波や大陸性の気候が卓越しやすくなる。\n\nNAO は北極振動の北大西洋域における現れとも位置づけられ、両者は密接に関係する。正の位相ではジェットが北寄りで強く、負の位相では南下・蛇行して欧州に寒波をもたらす。エルニーニョとは別の現象である。\n\n【図解】NAO の位相と天候\n　位相｜気圧差（アイスランドとアゾレス）｜ヨーロッパの天候\n　正｜大きい｜温暖・多雨\n　負｜小さい｜寒冷・乾燥や寒波\n　⇒ 気圧差の大小が北大西洋の偏西風の強さを決める\n　⚠ 正の位相でヨーロッパが寒冷乾燥とするのは逆。温暖多雨になりやすい。',
