    question: '太平洋十年規模振動（PDO：Pacific Decadal Oscillation）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'PDOは北太平洋の海面水温分布パターンが数年〜数十年という長い周期で変動する現象であり、エルニーニョ・ラニーニャ現象（数年規模）に比べてはるかに長い時間スケールで気候に影響を与えるとされる。', explanation: '正しい。PDOは北太平洋（特に中緯度〜北部）の海面水温がエルニーニョに似たパターンとその逆のパターンの間を数十年規模の長い周期で変動する現象であり、エルニーニョ・南方振動（ENSO、数年周期）よりはるかに長い時間スケールを持つ点が特徴とされる。' },
      { key: 'B', text: 'PDOはエルニーニョ現象と同じ数か月〜1、2年程度の短い周期で変動する現象である。', explanation: '誤り。PDOの周期はエルニーニョよりはるかに長く、数十年規模（一つの位相がおよそ20〜30年程度持続することもある）とされる点が特徴である。' },
      { key: 'C', text: 'PDOは大西洋の海面水温変動を表す指数である。', explanation: '誤り。PDOはその名の通り太平洋（特に北太平洋）の海面水温変動を表す指数であり、大西洋の現象ではない。' },
      { key: 'D', text: 'PDOは日本の気候には全く影響を与えない現象である。', explanation: '誤り。PDOは太平洋の海面水温分布を通じて大気循環に影響を与えるため、日本を含む北太平洋周辺の気候の長期変動（十年規模の傾向）にも影響を及ぼすと考えられている。' },
    ],
    correctKey: 'A',
    explanation: 'PDOは北太平洋の海面水温分布パターンが数十年規模の長い周期で変動する現象で、エルニーニョ・ラニーニャ（数年周期のENSO）とは時間スケールが大きく異なる。PDOの位相はエルニーニョの頻度や強度、日本を含む北太平洋周辺域の長期的な気候傾向にも影響を与えるとされる。\n\nPDO の正の位相では北太平洋中央部の水温が低く東部の沿岸が高くなる分布、負の位相では逆になる。この長期的な背景の違いが、同じエルニーニョでも影響の出方を変える要因となる。\n\n【図解】海洋変動の時間スケール\n　現象｜時間スケール｜おもな海域\n　ENSO（エルニーニョなど）｜数年｜熱帯太平洋\n　PDO｜数10年｜北太平洋\n　IOD｜数か月から1年｜熱帯インド洋\n　⇒ 時間スケールの違いが季節予報と気候予測の使い分けを生む\n　⚠ PDO をエルニーニョと同じ数年周期とするのは誤り。十年規模の変動である。',
