    question: 'インド洋ダイポールモード現象（IOD）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'IODは熱帯インド洋の東部（スマトラ島沖）と西部（アフリカ東岸沖）の海面水温偏差がシーソー的に変動する現象で、正の位相では西部で水温が高く東部で低くなり、東アフリカで多雨、インドネシア周辺で乾燥傾向になりやすい。', explanation: '正しい。IODは熱帯インド洋の東西の海面水温偏差のシーソー現象であり、正の位相では西インド洋（アフリカ東岸沖）で海面水温が平年より高く、東インド洋（スマトラ島沖）で低くなる。これにより東アフリカで多雨、インドネシア周辺で少雨傾向になるといった対照的な気候影響が生じる。' },
      { key: 'B', text: 'IODは太平洋の現象であり、インド洋とは無関係である。', explanation: '誤り。IODはその名の通りインド洋（特に熱帯インド洋）の海面水温偏差の東西のシーソー現象であり、太平洋の現象（エルニーニョなど）とは異なる海域の現象である。' },
      { key: 'C', text: 'IODの正の位相では、東インド洋（インドネシア周辺）で海面水温が高くなり多雨傾向となる。', explanation: '誤り。IODの正の位相では東インド洋（インドネシア周辺）はむしろ海面水温が低くなり、少雨（乾燥）傾向になりやすい。多雨になりやすいのは西インド洋（東アフリカ）側である。' },
      { key: 'D', text: 'IODはエルニーニョ現象と全く独立しており、両者の間には統計的な関連は一切見られない。', explanation: '誤り。IODとエルニーニョ現象（ENSO）は必ずしも独立ではなく、両者が同時に発生しやすい統計的な関連が指摘されており、共に発生した場合には気候影響が強まることもあるとされる。' },
    ],
    correctKey: 'A',
    explanation: 'IODは熱帯インド洋東西の海面水温偏差のシーソー現象で、正の位相では西インド洋（東アフリカ沖）で高水温・東インド洋（スマトラ沖）で低水温となり、東アフリカの多雨とインドネシア周辺の少雨をもたらす。IODはエルニーニョ・南方振動（ENSO）と統計的に関連することがあり、日本の天候にも間接的に影響しうるとされる。\n\n正の IOD では西インド洋で対流が活発化し東インド洋で抑制されるため、東アフリカで多雨、インドネシアやオーストラリアで少雨・干ばつとなる。エルニーニョと同時に起こることが多く、日本の夏の天候にも影響する。\n\n【図解】インド洋ダイポールモード\n　位相｜西インド洋｜東インド洋\n　正の位相｜高水温・多雨｜低水温・少雨\n　負の位相｜低水温・少雨｜高水温・多雨\n　⇒ 東西の水温偏差がシーソーのように逆位相で振れる\n　⚠ 正の位相で東インド洋が高水温・多雨とするのは東西が逆である。',
