    question: '極渦（冬季の極域成層圏に形成される低気圧性の循環）の構造変化のパターンに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '成層圏突然昇温が発生した際、極渦の変化パターンには、極渦が2つ（あるいはそれ以上）に分裂する「分裂型（split型）」と、極渦全体が極域から中緯度側へ大きくずれる「変位型（displacement型）」の2つの典型的な様式が知られている。', explanation: '正しい。成層圏突然昇温に伴う極渦の変形パターンは、プラネタリー波の波数2成分が卓越すると極渦が2つに分裂する分裂型（split型）、波数1成分が卓越すると極渦全体が中緯度側へ大きくずれる変位型（displacement型）に大別されることが研究により知られている。' },
      { key: 'B', text: '極渦は常に円形を保ったまま、位置や形状が変化することは一切ない。', explanation: '誤り。極渦は下から伝わるプラネタリー波の影響を受けて形状や位置が変化しやすく、成層圏突然昇温時には分裂や変位といった大きな構造変化を示すことがある。' },
      { key: 'C', text: '極渦の分裂・変位は対流圏の天候には全く影響を及ぼさない、成層圏のみで完結する現象である。', explanation: '誤り。極渦の崩壊（成層圏突然昇温）に伴う変化は、その後数週間にわたり対流圏の循環（北極振動の負の位相への転換など）に影響を及ぼし、中緯度の寒波などの一因となることが知られている。' },
      { key: 'D', text: '極渦は夏季の成層圏で最も強く発達する構造である。', explanation: '誤り。極渦は冬季の極域成層圏（極夜による著しい低温）で強く発達する構造であり、夏季には（東風が卓越し）極渦は形成されない。' },
    ],
    correctKey: 'A',
    explanation: '成層圏突然昇温に伴う極渦の変形は、プラネタリー波の卓越する波数成分に応じて、極渦が分裂する「分裂型」と極渦全体が中緯度側にずれる「変位型」の2つの典型的なパターンに分類される。極渦の崩壊はその後の対流圏循環（北極振動など）にも波及し、中緯度の寒波の一因となりうる。\n\n分裂型は波数2、変位型は波数1のプラネタリー波が卓越したときに起こりやすい。極渦の崩壊は数週間かけて対流圏へ影響が下りてきて、北極振動を負の位相に導き中緯度の寒波につながることがある。\n\n【図解】成層圏突然昇温の型\n　型｜極渦の変化｜卓越する波数\n　分裂型｜2つ以上に分かれる｜波数2\n　変位型｜中緯度側へずれる｜波数1\n　共通の影響｜極域成層圏の急昇温｜対流圏へ波及\n　⇒ 極渦の崩壊は数週間後の中緯度の寒波と結びつくことがある\n　⚠ 極渦は冬季に発達する。夏に最も強いとするのは誤り。',
