    explanation: '台風のエネルギー源は海面からの水蒸気の蒸発による潜熱供給であり、これが十分に得られる経験的な海面水温の目安としておおむね26〜27 °C以上（いわゆる26℃線）が古くから指摘されている。ただし発達には海面水温だけでなく、鉛直シアーの弱さや上層の発散状況など複数の環境条件が揃うことが必要である。\n\n海面水温が高いほど有利ではあるが、鉛直シアーが強ければ暖気核が崩れて発達できず、上層のアウトフローが悪ければ気圧は下がらない。また暖水層の厚さも重要で、表層だけ暖かい海域では強風によるかき混ぜで急速に冷えてしまう。\n\n【図解】台風の発生・発達の条件\n　条件｜必要な状態｜理由\n　海面水温｜約26〜27 ℃以上｜潜熱の供給\n　暖水層の厚さ｜厚い｜かき混ぜで冷えにくい\n　鉛直シアー｜弱い｜暖気核を保てる\n　緯度｜おおむね5度以上｜コリオリ力が必要\n　⇒ 水温だけでなく複数の環境条件がそろう必要がある\n　⚠ 目安を10 ℃程度とするのは誤り。約26〜27 ℃以上が経験的な基準である。',
