    explanation: '日本版改良藤田スケール（JEFスケール）は竜巻等の突風による様々な被害状況（建物・樹木・自動車など複数の被害指標）を総合的に評価して風速を推定する尺度で、JEF0からJEF5までの6段階に区分される。突風は狭い範囲で発生し観測が難しいため、被害調査に基づく事後的な評価が主な手法となる。\n\n竜巻は水平規模が数十〜数百 mと小さく、観測網で直接風速を捉えることはほとんどできない。そのため気象庁は現地に赴いて被害の状況を調査し、被害指標ごとに定められた風速の幅から推定風速を割り出す方式をとっている。\n\n【図解】JEFスケールの階級\n　階級｜推定風速（3秒平均）｜被害のめやす\n　JEF0｜25〜38 m/s｜物置や樹木の枝が損傷\n　JEF1｜39〜52 m/s｜屋根がめくれる\n　JEF3｜80〜97 m/s｜木造住宅が倒壊\n　JEF5｜126 m/s以上｜鉄骨も大きく変形\n　⇒ 数字が大きいほど風速が強く被害も甚大である\n　⚠ JEFスケールは被害調査から風速を推定する尺度で、風速計の直接観測ではない。',
