    question: '梅雨前線に伴う大雨と下層の水蒸気フラックス（水蒸気の輸送量）の収束の関係に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '梅雨前線付近の大雨は、南from太平洋高気圧の縁を回って流入する下層の暖湿な気流による水蒸気フラックスが前線帯で収束し、大量の水蒸気が持続的に供給・凝結することで強化される傾向がある。', explanation: '正しい。梅雨前線に沿う大雨は、太平洋高気圧の縁を回って流入する下層の暖湿な気流（しばしば下層ジェットとして観測される）が前線帯に持続的に水蒸気を運び込み、そこで収束することで大量の水蒸気供給と凝結が起こり、大雨がもたらされるという水蒸気フラックス収束の考え方で理解されることが多い。' },
      { key: 'B', text: '梅雨前線の大雨は水蒸気の輸送とは無関係に、気温差のみによって発生する現象である。', explanation: '誤り。梅雨前線の大雨には下層の暖湿な気流による持続的な水蒸気の供給・収束が本質的に重要な役割を果たしており、気温差のみで説明できる現象ではない。' },
      { key: 'C', text: '水蒸気フラックスの収束が大きいほど、その地域の降水量はむしろ少なくなる傾向がある。', explanation: '誤り。水蒸気フラックスの収束が大きいほど、その地域に持続的に水蒸気が供給・凝結されるため、降水量はむしろ多くなる傾向がある。' },
      { key: 'D', text: '梅雨前線付近の水蒸気フラックスは、北から南への流れによってのみ形成される。', explanation: '誤り。梅雨前線に大雨をもたらす水蒸気フラックスは、主に南（太平洋高気圧の縁）から北（前線帯）への暖湿気の流入によって形成されるものであり、記述の向きが逆である。' },
    ],
    correctKey: 'A',
    explanation: '梅雨前線の大雨は太平洋高気圧の縁を回って流入する下層の暖湿気流による水蒸気フラックスが前線帯で収束することで強化される。この水蒸気フラックス収束の考え方は大雨の実況監視・診断における重要な視点であり、下層ジェットの存在が確認されると大雨のポテンシャルが高いと評価される。\n\n水蒸気フラックスは風速と比湿の積で表され、その収束量が降水量とよく対応する。850 hPa の風と比湿から求めた水蒸気フラックス収束の分布は、大雨の位置を絞り込む実務的な資料として使われる。\n\n【図解】水蒸気フラックス収束の見方\n　要素｜内容｜大雨との関係\n　下層ジェット｜強い南西風｜輸送量を増やす\n　比湿｜高い｜輸送量を増やす\n　前線帯｜風が収束する｜水蒸気が集まる\n　⇒ 風速と比湿がともに大きく、そこで収束するときに大雨となる\n　⚠ 収束が大きいほど降水量が少ないとするのは逆である。',
