    subjectName: '予報業務に関する一般知識',
    question: 'ヒートアイランド現象に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'ヒートアイランド現象は、コンクリートやアスファルトなど熱容量が大きく蒸発による冷却効果の乏しい人工的な地表面が卓越する都市部で、郊外に比べて気温が高くなる現象であり、特に夜間の気温低下が郊外より小さくなる形で顕著に現れやすい。', explanation: '正しい。都市部ではコンクリートやアスファルトなど蒸発散による冷却効果が乏しい人工被覆が卓越し、日中に蓄えた熱を夜間に放出し続けるため、郊外に比べて気温（特に夜間の最低気温）が高くなる現象がヒートアイランドである。「島」のように都市部の気温が周囲より高くなる分布を示すことからこの名がある。' },
      { key: 'B', text: 'ヒートアイランド現象は主に日中の最高気温にのみ現れ、夜間の気温には影響しない。', explanation: '誤り。ヒートアイランド現象は日中に蓄積された熱が夜間に放出され続けることで、むしろ夜間の気温低下が郊外より小さくなる（最低気温が下がりにくい）形で顕著に現れることが多い。' },
      { key: 'C', text: 'ヒートアイランド現象は都市部の植生が豊富であるために生じる現象である。', explanation: '誤り。ヒートアイランド現象はむしろ都市部で植生（蒸発散による冷却効果を持つ）が乏しく、人工的な被覆（熱容量が大きく蒸発散の少ない）が卓越することによって生じる現象である。' },
      { key: 'D', text: 'ヒートアイランド現象は郊外の気温が都市部より高くなる現象を指す。', explanation: '誤り。ヒートアイランド現象は都市部の気温が郊外より高くなる現象を指すものであり、記述は関係が逆である。' },
    ],
    correctKey: 'A',
    explanation: 'ヒートアイランド現象は都市部の人工被覆（大きな熱容量・乏しい蒸発散）や人工排熱などにより、郊外に比べて気温が高くなる現象で、特に夜間の気温低下が小さくなる形で顕著に現れやすい。これにより局地的な循環（都市部への収束）が強化されることもあり、局地的な大雨の一因として研究されている。\n\n昼間は都市も郊外も日射で暖まるため差は小さいが、夜間は郊外が放射冷却で急速に冷えるのに対し、都市は昼に蓄えた熱を放出するため冷えにくく、気温差が最大になる。等温線が島のように閉じることから熱の島と呼ぶ。\n\n【図解】ヒートアイランドの要因\n　要因｜内容｜効果\n　人工被覆｜アスファルトやコンクリート｜熱を蓄えて夜に放出\n　蒸発散の減少｜緑地や水面が少ない｜気化熱による冷却がない\n　人工排熱｜空調や自動車｜直接的な加熱\n　⇒ 気温差は夜間から明け方にかけて最も大きくなる\n　⚠ 「日中の最高気温にのみ現れる」は誤り。夜間の高温化がより顕著である。',
    difficulty: 'basic',
    examYear: '令和3年',
