    correctKey: 'A',
    explanation: '海陸風は陸地と海面の熱容量の違いによる気温差（気圧差）を駆動力とする日変化の大きい局地循環である。日中は陸上が速く加熱されて低圧部となり海から陸へ海風が、夜間は陸上が速く冷えて陸から海へ陸風が吹く。この循環は快晴で総観規模の風が弱い日に特に明瞭に現れる。\n\n熱容量が小さい陸は日射で速く暖まり夜は速く冷えるのに対し、水は熱容量が大きく温度変化が緩やかである。この温度差が気圧差を作って循環が生じる。朝夕の切り替わりの時間帯には風が止む凪が現れる。\n\n【図解】海陸風の日変化\n　時間帯｜陸と海の気温｜吹く風\n　日中｜陸のほうが高温｜海風（海から陸へ）\n　夜間｜陸のほうが低温｜陸風（陸から海へ）\n　朝夕｜ほぼ同じ｜朝凪・夕凪\n　⇒ 総観規模の風が弱い晴天の日に明瞭に現れる\n　⚠ 日中に陸風、夜間に海風とするのは向きが完全に逆である。',
    difficulty: 'standard',
    examYear: '令和3年',
