    choices: [
      { key: 'A', text: '一般的な積乱雲では雲の上部に正電荷、下部に負電荷が蓄積される電荷構造をとることが多く、この場合に地上へ落ちる落雷は雲の下部の負電荷が放電する「負極性落雷」が大部分を占める。', explanation: '正しい。典型的な積乱雲の電荷構造は、雲の上部（氷晶が多い領域）に正電荷、中〜下部（あられ・雹が多い領域）に負電荷が分布する三極構造（さらに下部にわずかな正電荷を伴うこともある）をとることが多く、地上への落雷はこの下部の負電荷が放電する負極性落雷が大部分（8〜9割程度）を占めるとされる。' },
      { key: 'B', text: '落雷はすべて正極性落雷であり、負極性落雷という区分は存在しない。', explanation: '誤り。落雷には正極性落雷（雲の上部の正電荷が放電する）と負極性落雷（雲の下部の負電荷が放電する）の2種類があり、一般に負極性落雷の方が多くを占める。' },
      { key: 'C', text: '正極性落雷は一般に負極性落雷よりも発生頻度が高い。', explanation: '誤り。一般的な積乱雲による落雷では負極性落雷の方が多数（8〜9割程度）を占め、正極性落雷は少数派である（ただし正極性落雷はエネルギーが大きい傾向があり被害が大きくなりやすいとされる）。' },
      { key: 'D', text: '積乱雲内の電荷分離の機構は完全に解明されており、電荷分離には氷晶やあられなどの氷粒子は一切関与しない。', explanation: '誤り。積乱雲内の電荷分離機構は完全には解明されていない部分もあるが、氷晶とあられ（グラウペル）の衝突による電荷移動が主要な機構の一つと考えられており、氷粒子は電荷分離に本質的に関与するとされる。' },
    ],
    correctKey: 'A',
    explanation: '典型的な積乱雲は上部に正電荷、下部に負電荷を蓄積する電荷構造をとり、地上への落雷はこの下部負電荷による負極性落雷が大部分を占める。電荷分離の主要な機構としては、氷晶とあられ（グラウペル）の衝突による電荷の移動（非誘導帯電機構）が有力視されている。\n\n電荷分離は、あられと氷晶が過冷却水の存在下で衝突する際に、温度によって符号が変わる形で電荷をやりとりする非誘導帯電機構が有力とされる。落雷の大半は雲下部の負電荷によるが、雲頂が発達した冬季雷では正極性落雷の割合が高くなる。\n\n【図解】積乱雲の電荷構造\n　位置｜電荷｜落雷への関与\n　雲の上部｜正電荷｜正極性落雷（頻度は少ない）\n　雲の中下部｜負電荷｜負極性落雷（大部分）\n　雲底付近｜小さな正電荷域｜放電の起点になることも\n　⇒ 電荷分離にはあられと氷晶の衝突が不可欠である\n　⚠ 落雷が全て正極性とするのは誤り。大部分は負極性である。',
