    explanation: '夜間下層ジェットは、地表の放射冷却による境界層の急激な安定化とそれに伴う摩擦の減少により、風が慣性振動を通じて一時的に地衡風を超える速度まで加速する現象である。この現象は積乱雲への暖湿気の輸送を強化することがあり、夜間から早朝にかけての大雨の一因として注目されることがある。\n\n日中は乱流混合により上下の運動量が交換されて風が抑えられているが、夜間に安定化するとその結合が切れ、上空の空気が摩擦から解放されて加速する。慣性振動により地衡風を上回る超地衡風となり、明け方に最大となることが多い。\n\n【図解】夜間下層ジェットの成立\n　時間帯｜境界層の状態｜下層の風\n　日中｜混合層で摩擦が効く｜地衡風より弱い\n　日没後｜安定化し摩擦が減る｜加速を始める\n　深夜から明け方｜慣性振動｜地衡風を上回る\n　⇒ 慣性振動が関わるためコリオリ力が本質的な役割を果たす\n　⚠ 「日中の対流が活発な時間帯に形成」は誤り。夜間に安定化して形成される。',
