    subjectName: '予報業務に関する一般知識',
    question: '日本の内陸部で夏季にしばしば観測される猛暑（極端な高温）の複合的な形成要因に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '内陸部の猛暑は、太平洋高気圧の勢力下での下降流による断熱昇温、フェーン現象による山越え気流の昇温、都市化に伴うヒートアイランド現象など複数の要因が重なり合うことで、特に強い高温が発現することがある。', explanation: '正しい。内陸部で観測される極端な高温（猛暑日）は単一の要因だけでなく、太平洋高気圧に覆われることによる広域的な下降流（断熱昇温）、周辺の山地からの風の吹き下ろしに伴うフェーン現象（局地的な昇温）、都市部特有のヒートアイランド現象（人工被覆や排熱による昇温）などが複合的に重なることで、記録的な高温につながることが多いとされる。' },
      { key: 'B', text: '猛暑は単一の要因（太平洋高気圧の勢力のみ）によって決まり、地形やフェーン現象、都市化の影響は無視できる。', explanation: '誤り。猛暑の形成には太平洋高気圧による広域的な下降流だけでなく、フェーン現象や都市化（ヒートアイランド）といった地域固有の要因も重要な役割を果たしており、無視できるものではない。' },
      { key: 'C', text: 'フェーン現象は猛暑の形成には一切寄与しない。', explanation: '誤り。フェーン現象（山越え気流の断熱昇温）は内陸部の局地的な猛暑を強化する要因の一つとして知られており、実際に記録的な高温が観測された事例でフェーン現象の関与が指摘されることがある。' },
      { key: 'D', text: '猛暑は海に近い沿岸部でのみ発生し、内陸部では発生しない。', explanation: '誤り。猛暑（極端な高温）はむしろ海の冷却効果が及びにくい内陸部や盆地地形で顕著に発現しやすく、フェーン現象や地形の影響も加わりやすい地域として知られている。' },
    ],
    correctKey: 'A',
    explanation: '内陸部の猛暑は太平洋高気圧に伴う広域的な下降流（断熱昇温）に加え、フェーン現象による局地的な昇温、都市化によるヒートアイランド現象など複数の要因が複合的に重なることで、特に強い高温が発現することが多い。記録的な高温事例の解析ではこれら複数要因の寄与を総合的に評価することが重要とされる。\n\n記録的高温の事例では、上空の高気圧に伴う下降流で気層全体が昇温したうえに、山越えのフェーンが加わり、さらに都市の排熱が重なるという多重の要因が働く。要因の切り分けには数値実験による寄与度の評価が用いられる。\n\n【図解】猛暑をもたらす要因\n　要因｜スケール｜働き\n　太平洋高気圧の下降流｜総観規模｜断熱昇温\n　フェーン現象｜局地｜山越えによる昇温と乾燥\n　ヒートアイランド｜都市規模｜人工排熱と蓄熱\n　⇒ 記録的高温は複数の要因が重なったときに現れる\n　⚠ 単一の要因だけで説明できるとするのは誤り。複合的に評価する必要がある。',
