    subjectName: '予報業務に関する一般知識',
    question: '急速に発達する温帯低気圧（いわゆる「爆弾低気圧」）の発達基準に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '爆弾低気圧は、中心気圧が24時間で緯度に応じた基準（緯度60°で24 hPa相当となるよう正弦関数で補正した値）以上に低下する急速な発達を示す温帯低気圧を指す、気象学の研究上の経験的な定義に基づく呼称である。', explanation: '正しい。急速に発達する温帯低気圧の研究上の基準（サンダース・ガイアキスの基準）では、24時間あたりの中心気圧の低下量を緯度60°を基準として正弦関数で補正した値（1ベルゲロン）を用い、この補正済みの低下量がおよそ24 hPa以上となる急発達を示す低気圧を指して「爆弾低気圧（explosive cyclogenesis）」と呼ぶことが一般的である。' },
      { key: 'B', text: '爆弾低気圧という用語は気象業務法で正式に定義された法令用語である。', explanation: '誤り。「爆弾低気圧」は気象学・気象予報の分野で慣用的に使われる呼称であり、気象業務法など法令上で正式に定義された用語ではない。' },
      { key: 'C', text: '爆弾低気圧の基準となる気圧低下量は、緯度によらず一律24 hPa/24時間である。', explanation: '誤り。爆弾低気圧の基準は緯度によるコリオリパラメータの違いを考慮した正弦関数による補正がなされており、単純に緯度によらない一律の値ではない。' },
      { key: 'D', text: '爆弾低気圧は熱帯低気圧（台風）にのみ適用される用語であり、中緯度の温帯低気圧には使われない。', explanation: '誤り。「爆弾低気圧」はまさに中緯度の温帯低気圧の急速な発達現象を指す用語であり、熱帯低気圧（台風）に対しては通常この呼称は用いられない（台風の急発達は別途「急速強化」等の用語で表現される）。' },
    ],
    correctKey: 'A',
    explanation: '爆弾低気圧（急速に発達する温帯低気圧）は、24時間あたりの中心気圧低下量を緯度60°基準で正弦関数補正した値（1ベルゲロンあたり緯度60°で24 hPa/24時間相当）がおよそ1ベルゲロン以上となる急発達を示す温帯低気圧を指す研究上の呼称であり、傾圧不安定の急速な成長を反映した現象として位置づけられる。\n\n基準を緯度で補正するのは、コリオリパラメータが緯度により異なるためである。急発達には上層の強い正渦度移流、下層の暖気移流、暖流域からの潜熱供給が重なることが多く、日本の東海上は世界有数の急発達域として知られる。\n\n【図解】爆弾低気圧の要点\n　項目｜内容｜補足\n　定義｜24時間の気圧低下が基準以上｜緯度で補正\n　基準｜緯度60度で24 hPa/24時間｜1ベルゲロン\n　主な発生域｜日本の東海上や北大西洋｜暖流域の上\n　⇒ 傾圧不安定の急速な成長が背景にある\n　⚠ この用語は研究上の呼称であり、法令で定義された用語ではない。',
    difficulty: 'advanced',
