    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '主要な温室効果ガス（二酸化炭素、メタン、一酸化二窒素）の大気中滞留時間の違いに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'メタンの大気中の平均的な滞留時間はおよそ10年程度と比較的短いのに対し、二酸化炭素は複数の時間スケール（数十年から数百年、一部はさらに長期）にわたって大気中に残留し、一酸化二窒素の滞留時間はおよそ100年程度とされる。', explanation: '正しい。メタン（CH₄）は主に対流圏中のヒドロキシルラジカル（OHラジカル）との反応によって分解されるため大気中の滞留時間はおよそ10年程度と比較的短い。これに対し二酸化炭素（CO₂）は海洋・陸上生態系との交換や地質学的過程を含む複数の時間スケールで大気中に残留し、一部は数百年〜それ以上の非常に長期にわたって影響が続くとされる。一酸化二窒素（N₂O）の滞留時間はおよそ100年程度とされる。' },
      { key: 'B', text: '二酸化炭素の大気中滞留時間はメタンよりも短い。', explanation: '誤り。二酸化炭素はメタンよりもはるかに長期間（数十年から数百年以上）大気中に残留するとされ、両者の関係は記述とは逆である。' },
      { key: 'C', text: 'メタン・二酸化炭素・一酸化二窒素の大気中滞留時間はいずれもほぼ同じ（数年程度）である。', explanation: '誤り。これら3つの温室効果ガスの大気中滞留時間は種類によって大きく異なり（メタンは短く、二酸化炭素・一酸化二窒素はより長い）、一律に同じというわけではない。' },
      { key: 'D', text: '温室効果ガスの大気中滞留時間は、その気候変動への影響の評価には無関係な要素である。', explanation: '誤り。大気中滞留時間はその温室効果ガスが排出された後どれだけ長く気候への影響を及ぼし続けるかを左右する重要な要素であり、気候変動対策の検討（短寿命気候汚染物質対策など）において考慮される。' },
    ],
    correctKey: 'A',
    explanation: 'メタンは対流圏中のOHラジカルとの反応で分解されるため滞留時間はおよそ10年程度と短いのに対し、二酸化炭素は海洋・陸上生態系との交換や地質学的過程を含む複数の時間スケールで大気中に残留し数百年以上にわたり影響が続く。一酸化二窒素の滞留時間はおよそ100年程度とされ、これらの違いは各ガスの気候変動への長期的な寄与を評価する上で重要である。\n\n滞留時間の違いは、削減の効果がいつ現れるかを左右する。メタンは削減すれば10年程度で効果が現れるが、二酸化炭素は排出を止めても濃度がすぐには下がらず、温暖化の影響が長く残る。\n\n【図解】主な温室効果ガスの滞留時間\n　気体｜滞留時間｜主な消滅過程\n　メタン｜約10年｜OHラジカルとの反応\n　一酸化二窒素｜約100年｜成層圏での光分解\n　二酸化炭素｜数10年から数100年以上｜海洋と陸域への吸収\n　⇒ 滞留時間の長さがそのまま影響の持続期間になる\n　⚠ 二酸化炭素の滞留時間がメタンより短いとするのは逆である。',
