    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '氷床・海氷のアルベドフィードバック（アイスアルベドフィードバック）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '気温上昇により雪氷（アルベドが高い）が融けて海面や地表面（アルベドが低い）が露出すると、太陽放射の吸収量が増加してさらに気温が上昇し、雪氷の融解を促進するという正のフィードバック機構が働く。', explanation: '正しい。雪や氷はアルベド（反射率）が高く（新雪で約0.8〜0.9）、太陽放射の大部分を反射するが、これが融けて下にある海面（アルベド約0.06〜0.1）や地表面（植生・裸地で0.1〜0.3程度）が露出すると、太陽放射の吸収量が大きく増加し、さらなる昇温・融解を招くという正のフィードバック機構（アイスアルベドフィードバック）が働く。このフィードバックは北極域で温暖化が世界平均より速く進む「北極増幅」の主要な要因の一つとされる。' },
      { key: 'B', text: 'アイスアルベドフィードバックは気温の変化を打ち消す方向に働く負のフィードバックである。', explanation: '誤り。アイスアルベドフィードバックは気温上昇→雪氷融解→アルベド低下→吸収増加→さらなる気温上昇、という自己増幅的な正のフィードバックであり、変化を打ち消す負のフィードバックではない。' },
      { key: 'C', text: '海面のアルベドは新雪のアルベドよりも高い。', explanation: '誤り。海面のアルベドはおよそ0.06〜0.1程度と非常に低く、新雪のアルベド（約0.8〜0.9）よりもはるかに低い。この差の大きさがアイスアルベドフィードバックを強力なものにしている。' },
      { key: 'D', text: 'アイスアルベドフィードバックは熱帯域で最も強く働くフィードバック機構である。', explanation: '誤り。アイスアルベドフィードバックは雪氷が存在する高緯度域（特に北極域）で最も強く働くフィードバック機構であり、雪氷がほとんど存在しない熱帯域では働きにくい。' },
    ],
    correctKey: 'A',
    explanation: 'アイスアルベドフィードバックは、雪氷（高アルベド）の融解によって露出する海面・地表面（低アルベド）が太陽放射の吸収を増加させ、さらなる昇温・融解を促す正のフィードバック機構である。このフィードバックは高緯度（特に北極域）で強く働き、世界平均を上回るペースで進行する「北極増幅」の主要因の一つとされている。\n\n新雪のアルベドが0.8〜0.9 であるのに対し、海面は0.1 程度と大きな差がある。この差が大きいため、雪氷が減るとその場所の吸収が急増する。北極域で世界平均の2〜3倍の速さで昇温する北極増幅の主因である。\n\n【図解】アイスアルベドフィードバック\n　段階｜起きること｜次の段階へ\n　昇温｜雪氷が融ける｜地表が露出\n　露出｜アルベドが低下｜吸収が増える\n　吸収増｜さらに昇温｜融解が進む\n　⇒ 変化を増幅する正のフィードバックであり、高緯度で強く働く\n　⚠ 海面のアルベドが新雪より高いとするのは逆。負のフィードバックとするのも誤り。',
    difficulty: 'advanced',
