    question: '長期の気温変化の統計解析における「都市化バイアス（ヒートアイランドの影響）」の補正に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '都市化が進んだ観測地点ではヒートアイランド現象の影響により見かけ上の昇温トレンドが強調されることがあるため、世界平均気温の長期変化を評価する際には、都市化の影響が少ない観測点との比較検証や統計的な均質化処理によって、都市化バイアスの影響をできるだけ取り除く工夫がなされている。', explanation: '正しい。都市化が進んだ地点ではヒートアイランド現象により観測される気温上昇トレンドが、広域的な気候変動によるトレンドに都市化の影響が上乗せされたものになりうる。このため気象機関や研究機関では、都市化の影響が少ない地点との比較や、統計的な均質化（ホモジナイゼーション）処理によって、都市化バイアスの影響を可能な限り除去する品質管理を行っている。' },
      { key: 'B', text: '都市化バイアスは気温の長期トレンド評価には全く影響を与えないため、補正の必要はない。', explanation: '誤り。都市化バイアスは観測された気温トレンドに影響を与えうる要因であり、正確な広域的気候変動の評価のためには適切な補正・品質管理が必要とされる。' },
      { key: 'C', text: '都市化バイアスの補正を行うと、観測された昇温トレンドは実際よりも大きく見積もられるようになる。', explanation: '誤り。都市化バイアスの補正は、都市化の影響で見かけ上強調された昇温トレンドを取り除く（適正化する）ための処理であり、補正後のトレンドは通常、補正前よりも小さくなる（あるいはより正確な値になる）方向に働く。' },
      { key: 'D', text: '気象庁や気象機関はヒートアイランドの影響が疑われる地点も含め、いかなる補正も行わずに生の観測データをそのまま気候変動の指標として公表している。', explanation: '誤り。気象機関は都市化の影響を含む様々な観測環境の変化（測器の変更、観測点の移転など）を考慮した均質化処理を経たデータを用いて長期の気候変動の評価を行っている。' },
    ],
    correctKey: 'A',
    explanation: '都市化が進んだ観測地点ではヒートアイランド現象により見かけ上の昇温トレンドが強調されうるため、世界・日本の平均気温の長期変化を評価する際には、都市化の影響が少ない地点との比較や統計的な均質化処理によって、このバイアスをできるだけ取り除く品質管理が行われている。\n\n日本の気温の長期変化を評価する際、気象庁は都市化の影響が比較的小さい網走や寿都など15地点を選んで解析している。均質化処理では、観測地点の移転や測器の変更による不連続も併せて補正する。\n\n【図解】気温データの品質管理\n　バイアスの要因｜内容｜補正の方法\n　都市化｜ヒートアイランドで昇温が過大｜都市化の小さい地点を選ぶ\n　観測地点の移転｜不連続な段差｜統計的な均質化\n　測器の変更｜系統的な差｜比較観測で補正\n　⇒ 補正により見かけの昇温は小さくなる方向へ調整される\n　⚠ 補正でトレンドが大きく見積もられるとするのは逆。過大評価を取り除く処理である。',
    difficulty: 'standard',
