    correctKey: 'A',
    explanation: '検出と要因分析は、気候モデルによる自然要因のみのシミュレーションと自然＋人為起源要因を含むシミュレーションを観測データと比較することで、観測された気温上昇トレンドに対する人為起源の寄与を統計的に評価する手法である。この手法に基づき、近年の顕著な温暖化は人為起源の温室効果ガス増加が主要因であるとの科学的知見が得られている。\n\nこの手法では、観測された気温変化の時間的なパターンや空間分布を、モデルが再現するそれぞれの要因の指紋と照合する。自然要因だけでは20世紀後半以降の昇温を説明できず、人為要因を加えて初めて再現できることが示されている。\n\n【図解】検出と要因分析の手順\n　実験｜含める要因｜観測との一致\n　自然要因のみ｜太陽活動と火山活動｜近年の昇温を再現できない\n　人為要因のみ｜温室効果ガスとエアロゾル｜昇温傾向を再現\n　両方を含む｜自然と人為の両方｜観測と最もよく一致\n　⇒ 内部変動の幅を考慮したうえで統計的に寄与を評価する\n　⚠ 「観測データのみで行う」「自然要因だけで説明できる」はいずれも誤り。',
