    explanation: '気温上昇に伴う飽和水蒸気圧の増加（クラウジウス・クラペイロンの関係）により大気中の水蒸気量が増加し、強力な温室効果ガスである水蒸気の増加がさらなる温暖化を促進する正のフィードバック（水蒸気フィードバック）が働く。このフィードバックは気候感度の評価において最も影響の大きい要素の一つとされ、単純な二酸化炭素のみの放射強制力から予想される以上の温暖化をもたらすことが知られている。\n\n水蒸気は寿命が数日と短く、量は気温に従って決まるため、それ自体は温暖化の引き金にはならず増幅役として働く。この効果だけで二酸化炭素倍増による昇温はおよそ2倍になると見積もられている。\n\n【図解】主要なフィードバック\n　種類｜符号｜内容\n　水蒸気｜正｜昇温で水蒸気が増え温室効果が強まる\n　雪氷アルベド｜正｜雪氷が減り吸収が増える\n　黒体放射｜負｜昇温で射出が増える\n　⇒ 水蒸気は引き金ではなく増幅役として働く\n　⚠ 水蒸気フィードバックを負とするのは誤り。温暖化を強める正のフィードバック。',
