    choices: [
      { key: 'A', text: 'エアロゾルの直接効果とは、エアロゾル自体の粒子が太陽放射を直接散乱・吸収することによって放射収支に影響を与える効果であり、硫酸塩エアロゾルのように主に散乱によって太陽放射を宇宙空間へ反射し地表を冷却する効果を持つものと、ブラックカーボン（すす）のように主に吸収によって大気を加熱する効果を持つものとがある。', explanation: '正しい。エアロゾルの直接効果は粒子自体による太陽放射の散乱・吸収の効果を指し、硫酸塩エアロゾルなど散乱性の強い粒子は太陽放射を宇宙へ反射することで地表を冷却する方向（負の放射強制力）に働き、ブラックカーボンなど吸収性の強い粒子は大気を直接加熱する方向（正の放射強制力）に働くというように、エアロゾルの種類によって効果の向きが異なる点が特徴である。' },
      { key: 'B', text: 'エアロゾルの直接効果とは、エアロゾルが雲凝結核として働くことで雲の性質を変化させる効果を指す。', explanation: '誤り。これはエアロゾルの「間接効果」の説明である。「直接効果」はエアロゾル自体の粒子による太陽放射の散乱・吸収を指す。' },
      { key: 'C', text: 'すべてのエアロゾルは直接効果として大気を加熱する方向にのみ働く。', explanation: '誤り。エアロゾルの直接効果は種類によって異なり、散乱性の強い硫酸塩エアロゾルなどは冷却方向（負の放射強制力）に働くため、加熱方向にのみ働くという記述は誤りである。' },
      { key: 'D', text: 'エアロゾルの直接効果は温室効果ガスの効果と全く同じ物理過程（赤外線の吸収・再放射）によって生じる。', explanation: '誤り。温室効果ガスは主に地球からの赤外放射を吸収・再放射することで温室効果をもたらすのに対し、エアロゾルの直接効果は主に太陽放射（短波放射）の散乱・吸収による効果であり、物理過程が異なる。' },
    ],
    correctKey: 'A',
    explanation: 'エアロゾルの直接効果はエアロゾル粒子自体による太陽放射の散乱・吸収を指し、硫酸塩エアロゾルなど散乱性の強いものは冷却方向、ブラックカーボンなど吸収性の強いものは加熱方向に働くというように、エアロゾルの種類（組成）によって効果の向きが異なる点が特徴である。この直接効果は雲の性質を変化させる間接効果とは区別される。\n\n硫酸塩エアロゾルは光をよく散乱するため入射日射を減らして冷却に働き、ブラックカーボンは光を吸収するため大気を加熱し、雪面に沈着するとアルベドを下げてさらに融解を促す。効果の向きが組成で変わる点が要点である。\n\n【図解】エアロゾルの効果\n　種類｜光学的性質｜放射への影響\n　硫酸塩｜強く散乱する｜冷却\n　ブラックカーボン｜強く吸収する｜加熱\n　鉱物ダスト｜散乱と吸収の両方｜条件による\n　⇒ 直接効果は粒子自体の散乱・吸収、間接効果は雲を介した作用である\n　⚠ 「すべてのエアロゾルが加熱側に働く」は誤り。多くは冷却側に働く。',
