    id: 'kisho_gakka1_354',
    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '特別警報制度の趣旨に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '特別警報は、重大な災害の発生するおそれが著しく大きい場合に、通常の警報基準をはるかに超える豪雨や台風等が予想されるときに発表され、これを受けた市町村や住民に対してこれまでに経験したことのないような重大な危険が差し迫っていることを伝える趣旨の制度である。', explanation: '正しい。特別警報は東日本大震災における津波被害等を教訓に、重大な災害の発生するおそれが著しく大きい場合に、通常の警報の基準をはるかに超える現象が予想されるときに発表される制度として設けられた。数十年に一度あるかないかの重大な危険が差し迫っていることを住民に強く伝える趣旨を持つ。' },
      { key: 'B', text: '特別警報は通常の警報と全く同じ基準で発表され、名称のみが異なる制度である。', explanation: '誤り。特別警報は通常の警報の基準をはるかに超える、より重大な災害のおそれが著しく大きい場合に限って発表される、警報とは異なる基準を持つ制度である。' },
      { key: 'C', text: '特別警報は日常的に頻繁に発表されることを想定した制度である。', explanation: '誤り。特別警報は数十年に一度あるかないかという、きわめて重大で稀な災害のおそれがある場合に限って発表することを想定した制度であり、頻繁な発表は想定されていない。' },
      { key: 'D', text: '特別警報の発表は市町村長の権限であり、気象庁の業務ではない。', explanation: '誤り。特別警報の発表は気象庁の業務であり、市町村長はこれを受けて住民への周知等の対応を行う立場にある。' },
    ],
    correctKey: 'A',
    explanation: '特別警報は、重大な災害の発生するおそれが著しく大きい場合（数十年に一度あるかないかの現象が予想される場合など）に、通常の警報基準をはるかに超えるレベルの危険を住民に強く伝えるために設けられた制度であり、東日本大震災を教訓として警報制度の強化を図る趣旨で導入された。\n\n特別警報は2013年8月に運用が始まり、東日本大震災や紀伊半島大水害の教訓を踏まえて設けられた。数十年に一度の現象が対象なので発表頻度は低く、発表時点ですでに災害が発生している可能性が高い。\n\n【図解】特別警報の位置づけ\n　区分｜発表の目安｜求められる行動\n　注意報｜災害のおそれ｜今後の情報に注意\n　警報｜重大な災害のおそれ｜避難の準備と行動\n　特別警報｜数10年に一度の現象｜直ちに命を守る行動\n　⇒ 通常の警報基準をはるかに超える場合に限って発表される\n　⚠ 発表権限は気象庁にある。市町村長が発表するとするのは誤り。',
