    explanation: '気象業務法第6条は、気象庁以外の者が一定の要件を満たす気象観測を行う場合に気象庁長官への届出を求める規定であり、届出を要する観測は気象庁の定める技術上の基準に従うことが求められる。これにより民間の観測データについても一定の技術的信頼性が確保される仕組みとなっている。\n\n届出が必要なのは、観測成果を発表する場合や災害の防止に利用する場合などで、個人が趣味で行い外部に発表しない観測は対象外である。届出を要する観測には技術上の基準への適合と、検定を受けた測器の使用が求められる。\n\n【図解】気象観測の届出制度\n　場合｜届出｜測器\n　成果を発表する｜必要｜検定合格品を使用\n　災害防止に利用する｜必要｜検定合格品を使用\n　個人の趣味で発表しない｜不要｜制限なし\n　⇒ 公に使われる観測データの信頼性を確保するための制度である\n　⚠ 私的な観測まで一律に届出が必要とするのは誤り。気象庁自身の観測も対象外。',
