    explanation: '気象業務法は観測・予報の対象を「気象」（大気の諸現象）、「地象」（地震・火山現象を除く地面又は地中の諸現象）、「水象」（気象又は地象に密接に関連する陸水又は海水の諸現象）という3つの区分で定義している。地震動・火山現象が「地象」から除外されている点は予報業務許可制度の対象範囲を理解する上で重要である。\n\n地震動と火山現象が地象から除かれているのは、これらの予報が気象庁の専管とされているためである。水象には海水だけでなく陸水すなわち河川や湖沼の現象も含まれるので、洪水予報も対象になる。\n\n【図解】法律上の3区分\n　区分｜内容｜除外されるもの\n　気象｜大気の諸現象｜―\n　地象｜地面や地中の諸現象｜地震動と火山現象\n　水象｜陸水と海水の諸現象｜―\n　⇒ 除外規定があるのは地象だけである\n　⚠ 水象を海水だけとするのは誤り。河川や湖沼などの陸水も含まれる。',
