    explanation: '特別警報の対象となる現象は大雨・暴風・暴風雪・大雪・高潮・波浪といった気象に関する現象に加え、津波（大津波警報が特別警報に位置づけられる）や火山現象（噴火警報の特別警報級のもの）も含まれ、気象以外の分野にも及んでいる点に注意が必要である。\n\n気象分野の6種類に加え、津波では大津波警報が、火山では噴火警報のうち居住地域に重大な被害が及ぶものが特別警報に位置づけられ、地震では緊急地震速報の震度6弱以上のものが該当する。対象は気象以外にも及ぶ。\n\n【図解】特別警報の対象\n　分野｜該当するもの｜備考\n　気象｜大雨・暴風・暴風雪・大雪・高潮・波浪｜6種類\n　津波｜大津波警報｜特別警報に位置づけ\n　火山｜噴火警報（居住地域）｜レベル4以上に相当\n　地震｜緊急地震速報（震度6弱以上）｜特別警報に位置づけ\n　⇒ 気象以外の分野にも特別警報の枠組みが及んでいる\n　⚠ 対象を大雨と暴風の2種類だけとするのも、津波や火山を除くとするのも誤り。',
