    correctKey: 'A',
    explanation: '「警報」「注意報」は気象業務法に基づき、重大な災害等のおそれがある場合に発表される制度上明確に位置づけられた発表であるのに対し、竜巻注意情報などの「気象情報」は、これらを補足し、より詳細な状況や危険度の高まりを伝えるために気象庁が発表する情報として、異なる位置づけを持つ。\n\n気象情報には、警報や注意報に先立って発表する予告的なものや、発表中の警報を補足するもの、災害発生の危険度を伝えるものがある。竜巻注意情報や記録的短時間大雨情報がその例で、警報とは別の位置づけである。\n\n【図解】気象庁の発表の種類\n　種類｜位置づけ｜例\n　注意報・警報・特別警報｜法律上の制度｜大雨警報など\n　気象情報｜警報等を補足｜竜巻注意情報・記録的短時間大雨情報\n　ナウキャスト｜短時間の予測図｜降水や竜巻発生確度\n　⇒ 気象情報は警報を補い、より詳細な危険度を伝える役割をもつ\n　⚠ 竜巻注意情報を警報の一種とするのは誤り。位置づけが異なる。',
    difficulty: 'standard',
