    explanation: '予報業務の許可制度は独自に「現象の予想」を業として提供する行為を対象とするものであり、気象庁の発表した予報を単に受信・閲覧して自らの事業判断の参考として内部的に利用するにとどまる行為は、通常は許可を要しないと解される。この区別は民間事業者が気象データを業務利用する際に実務上重要となる考え方である。\n\n許可が必要になるのは、独自の予想を業として第三者に提供する場合である。自社の作業計画に使うだけの内部利用や、既存の予報を参考にするだけの行為は、事業規模の大小にかかわらず許可の対象にならない。\n\n【図解】許可の要否の判断\n　行為｜第三者への提供｜許可\n　気象庁の予報を内部で参考にする｜なし｜不要\n　自社の作業判断に使う｜なし｜不要\n　独自の予想を顧客に提供｜あり｜必要\n　⇒ 独自の予想を業として外部に提供するかどうかが基準である\n　⚠ 事業規模が大きいだけで許可が必要になるわけではない。',
