    explanation: '気象業務法第1条は「気象業務に関する国際的な協力を行うことができるようにすること」を法の目的の一つとして掲げており、気象庁は世界気象機関（WMO）等の国際的な枠組みを通じて、観測データの相互交換や予報技術の国際協力に参画している。気象現象が国境を越えて連続する性質上、国際協力は防災上も重要な意義を持つ。\n\nWMOは国連の専門機関で、全球通信システムを通じて各国の観測データがリアルタイムで交換されている。数値予報は地球全体の初期値を必要とするため、国際的なデータ交換なしには成り立たない。\n\n【図解】気象業務の国際協力\n　枠組み｜内容｜意義\n　WMO｜国連の専門機関｜基準の統一と協力\n　全球通信システム｜観測データの相互交換｜数値予報の初期値\n　台風委員会など｜地域単位の協力｜台風の番号や名称\n　⇒ 気象現象は国境を越えるため国際協力が不可欠である\n　⚠ WMOは民間企業ではなく、国連の専門機関である。',
    difficulty: 'standard',
