    choices: [
      { key: 'A', text: '虹は空気中の水滴による太陽光の屈折・反射・分散によって生じる現象であるのに対し、暈（太陽や月の周りに見える光の輪）は主に巻層雲などに含まれる氷晶による太陽光・月光の屈折によって生じる現象であり、両者は関与する粒子（水滴か氷晶か）が異なる。', explanation: '正しい。虹は雨粒（水滴）内部で太陽光が屈折・全反射・再屈折する際に波長ごとに屈折角がわずかに異なる（分散）ことで生じる現象である。一方、暈は巻層雲などに含まれる六角柱状の氷晶を光が屈折して通過する際に生じる現象であり、水滴による虹とは関与する粒子の種類（水滴か氷晶か）が異なる、別の光学現象である。' },
      { key: 'B', text: '虹と暈はいずれも同じ水滴による同じ物理過程（反射のみ）で生じる、本質的に同一の現象である。', explanation: '誤り。虹は水滴による屈折・反射・分散、暈は氷晶による屈折という異なる物理過程・異なる粒子に基づく現象であり、本質的に同一のものではない。' },
      { key: 'C', text: '暈は水滴によってのみ生じ、氷晶とは無関係な現象である。', explanation: '誤り。暈は主に巻層雲などに含まれる氷晶（六角柱状の結晶）による光の屈折で生じる現象であり、氷晶が本質的に関与する。' },
      { key: 'D', text: '虹や暈のような大気光学現象は、大気中の光の散乱・屈折とは無関係な、電磁気学的な放電現象である。', explanation: '誤り。虹や暈は太陽光や月光が大気中の水滴・氷晶によって屈折・反射・散乱されることで生じる光学現象であり、雷のような放電現象とは全く異なる物理過程に基づく。' },
    ],
    correctKey: 'A',
    explanation: '虹は水滴内部での太陽光の屈折・全反射・再屈折（および波長による分散）で生じる現象であり、暈は巻層雲などの氷晶による光の屈折で生じる現象である。両者は見た目が似ていても、関与する粒子の種類（水滴か氷晶か）と光の経路が異なる、区別すべき大気光学現象である。\n\n虹は水滴中で1回反射する主虹が視半径約42度、2回反射する副虹が約51度に見え、副虹では色の並びが逆になる。暈は六角柱状の氷晶での屈折によるもので、内暈が視半径約22度、外暈が約46度に現れる。\n\n【図解】主な大気光学現象\n　現象｜関与する粒子｜見え方\n　主虹｜水滴（1回反射）｜視半径約42度・外側が赤\n　副虹｜水滴（2回反射）｜視半径約51度・色が逆\n　内暈｜氷晶（屈折）｜太陽の周り約22度\n　彩雲｜小さな水滴（回折）｜雲の縁が色づく\n　⇒ 水滴によるものか氷晶によるものかで現象が分かれる\n　⚠ 虹と暈を同じ過程とするのも、暈を水滴由来とするのも誤り。',
