    choices: [
      { key: 'A', text: '蜃気楼は地表付近の気温の鉛直分布が急激に変化する（強い逆転層や強い気温減率の層が存在する）場合に、空気の密度差に応じて光の屈折率が変化し、光の進路が曲げられることで、実際の物体とは異なる位置や形状の像が見える現象である。', explanation: '正しい。大気の屈折率は密度（およびそれに関連する気温）に依存するため、地表付近に強い逆転層（上暖下冷）や強い気温減率の層（上冷下暖、逃げ水の原因）が存在すると、これらの層を通過する光が徐々に屈折し、進路が曲げられる。この結果、実際の物体の位置や形状とは異なる、浮き上がった像や反転した像などが観測される現象が蜃気楼である。' },
      { key: 'B', text: '蜃気楼は気温の鉛直分布が完全に一様（変化がない）な場合にのみ発生する現象である。', explanation: '誤り。蜃気楼はむしろ気温の鉛直分布が急激に変化する（不均一である）場合に、光の屈折率の急変によって生じる現象であり、一様な気温分布では発生しない。' },
      { key: 'C', text: '蜃気楼は音波の屈折によって生じる聴覚上の現象であり、光とは無関係である。', explanation: '誤り。蜃気楼は光（電磁波）の屈折によって生じる視覚上の現象であり、音波の屈折とは異なる（ただし音波にも同様の屈折現象が生じることはある）。' },
      { key: 'D', text: '蜃気楼の発生には大気の密度分布は全く関係せず、専ら地表面の色によって決まる。', explanation: '誤り。蜃気楼の発生は大気の密度分布（気温分布に対応する屈折率の勾配）に本質的に関係する現象であり、地表面の色によって決まるものではない。' },
    ],
    correctKey: 'A',
    explanation: '蜃気楼は地表付近の気温の急激な鉛直変化（強い逆転層や強い気温減率）により大気の屈折率が急変し、光の進路が曲げられることで、実際とは異なる位置・形状の像が見える現象である。冷たい海面上で見られる「浮き上がり」型と、熱せられた路面上で見られる「逃げ水」型など、気温分布のパターンによって異なる種類の蜃気楼が生じる。\n\n下暖上冷の強い減率がある熱せられた路面では光が下に凸に曲がり、実像の下に上下反転した像が見える下位蜃気楼（逃げ水）となる。逆に冷たい海面上の逆転層では光が上に凸に曲がり、物体が浮き上がって見える上位蜃気楼になる。\n\n【図解】蜃気楼の型\n　型｜気温の鉛直分布｜見え方\n　下位蜃気楼｜地表付近が高温｜像が下に反転（逃げ水）\n　上位蜃気楼｜地表付近が低温（逆転層）｜像が浮き上がる\n　⇒ 光は屈折率の大きい（低温で密な）側へ曲がる\n　⚠ 気温分布が一様なら屈折率も一様で、蜃気楼は生じない。',
