    subjectName: '予報業務に関する一般知識',
    question: '日没・日出時に空が赤く見える理由に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '太陽が水平線に近い日没・日出時には、太陽光が大気中を通過する経路（光路長）が日中に比べてはるかに長くなるため、波長の短い青色光の大部分が途中でレイリー散乱によって散らされてしまい、散乱されにくい波長の長い赤色系の光が相対的に多く直接目に届くようになる。', explanation: '正しい。太陽高度が低い日没・日出時には太陽光が大気中を通過する距離（光路長）が真昼に比べて何倍にも長くなる。レイリー散乱は波長の短い光ほど強く生じるため、この長い光路の途中で青色光の大部分が散乱されて失われ、相対的に散乱されにくい赤色系の光が直接目に届く割合が増えることで、太陽やその周辺の空が赤く見える。' },
      { key: 'B', text: '日没・日出時に空が赤く見える現象は、太陽自体が放射する光の色が時間帯によって変化するためである。', explanation: '誤り。太陽自体が放射する光のスペクトル（色）は時間帯によって本質的に変化するものではなく、地表に到達するまでの大気中での光路長の違いによる散乱の効果（レイリー散乱）によって見かけの色が変化する。' },
      { key: 'C', text: '日没・日出時には光路長がむしろ短くなるため、赤色光が強調される。', explanation: '誤り。日没・日出時には太陽高度が低いため、光が大気中を通過する経路（光路長）はむしろ真昼よりも長くなる。この光路長の増大こそが赤色光が強調される理由である。' },
      { key: 'D', text: '日没・日出時の空の赤さは、大気中のちり（エアロゾル）の吸収のみによって生じ、レイリー散乱とは無関係である。', explanation: '誤り。日没・日出時の赤さの主な原因は大気分子によるレイリー散乱（波長依存性）であり、エアロゾルによる吸収・散乱も色合いに一定の影響を与えるが、基本的なメカニズムはレイリー散乱に基づくものである。' },
    ],
    correctKey: 'A',
    explanation: '日没・日出時は太陽高度が低いため光路長が長くなり、波長の短い青色光がレイリー散乱によって途中で散らされて失われる一方、散乱されにくい赤色系の光が相対的に多く直接目に届く。これが空や太陽が赤く（オレンジ色に）見える理由であり、空が青く見える理由（レイリー散乱の波長依存性）と表裏一体の現象である。\n\n太陽高度が90度のとき光路長を1とすると、水平線付近では大気の層を約38倍も通る。その間に青い光は散乱されて横へ逃げ、残った赤い光が直接届くため、太陽も空も赤く見える。\n\n【図解】太陽高度と光路長\n　太陽高度｜光路長の比｜見える色\n　90度（真上）｜1｜白っぽい\n　30度｜約2｜やや黄色\n　0度（水平線）｜約38｜赤やオレンジ\n　⇒ 光路長が長いほど青い光が失われ赤みが増す\n　⚠ 太陽自体の光の色が変わるのではない。大気を通る距離の違いによる。',
