    question: '気象衛星の水蒸気画像の解釈に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '水蒸気画像は主に対流圏中上層の水蒸気による赤外放射の吸収を捉えたものであり、画像上で白く（明るく）見える領域は上層が湿潤であること、暗く（黒く）見える領域は上層が乾燥していることをそれぞれ示す。', explanation: '正しい。水蒸気画像は水蒸気が強く吸収する波長帯（およそ6.2μm付近）の赤外放射を観測するもので、対流圏中上層の水蒸気の多寡を反映する。上層に水蒸気が多い（湿潤な）領域では、より高い高度（低温）からの放射が観測されるため画像上で白く明るく表示され、逆に上層が乾燥している領域ではより低い高度（高温）からの放射が観測されるため暗く表示される。' },
      { key: 'B', text: '水蒸気画像は地表付近の水蒸気量のみを反映し、上層大気の状態とは無関係である。', explanation: '誤り。水蒸気画像はむしろ対流圏中上層の水蒸気を反映するものであり、地表付近の水蒸気量を直接示すものではない。' },
      { key: 'C', text: '水蒸気画像で白く（明るく）見える領域は、上層が乾燥していることを示す。', explanation: '誤り。関係が逆である。水蒸気画像で白く明るく見える領域は上層が湿潤であることを、暗く見える領域は上層が乾燥していることを示す。' },
      { key: 'D', text: '水蒸気画像は夜間には観測することができない。', explanation: '誤り。水蒸気画像は赤外放射（水蒸気による吸収帯の放射）を観測するものであり、可視画像とは異なり太陽光に依存しないため、夜間でも観測可能である。' },
    ],
    correctKey: 'A',
    explanation: '水蒸気画像は水蒸気の強い吸収帯（およそ6.2μm）の赤外放射を観測し、対流圏中上層の水蒸気の多寡を可視化する。上層が湿潤な領域は白く明るく、乾燥した領域は暗く表示され、上層のトラフやジェット気流に伴う乾燥貫入（ドライスロット）の把握など、総観規模の解析に広く利用される。\n\n水蒸気画像で暗く見える乾燥域は、成層圏起源の空気が対流圏へ降りてきた場所であることが多く、上層のトラフや渦度の極大と対応する。低気圧の後面に暗域が入り込むドライスロットは、低気圧の発達段階を示す手がかりとなる。\n\n【図解】水蒸気画像の読み取り\n　見え方｜輝度温度｜示すもの\n　白く明るい｜低い｜中上層が湿潤\n　暗い（暗域）｜高い｜中上層が乾燥\n　暗域の侵入｜―｜上層の乾燥貫入とトラフ\n　⇒ 雲がなくても上層の流れの構造を読み取れる点が長所である\n　⚠ 白い領域を乾燥とするのは逆。また赤外観測なので夜間も利用できる。',
