    choices: [
      { key: 'A', text: 'スパゲッティ図は、アンサンブル予報の各メンバーが予測した特定の等値線（例えば500 hPa面の特定の高度の等高度線）を重ねて1枚の図に描いたものであり、線の束が密集している（ばらつきが小さい）領域ほど予測の信頼性が高く、線が大きく広がっている（ばらつきが大きい）領域ほど予測の不確実性が高いことを示す。', explanation: '正しい。スパゲッティ図はアンサンブル予報の各メンバーが予測する特定の等値線（500 hPaの特定高度の等高度線など）を1枚の図上に重ねて描いたもので、麺（スパゲッティ）が絡み合ったように見えることからこの名がある。線が密集して束になっている領域は各メンバー間の予測のばらつきが小さく予測の信頼性が高いことを、線が広く分散している領域はばらつきが大きく予測の不確実性が高いことを視覚的に示す。' },
      { key: 'B', text: 'スパゲッティ図は単一の決定論的予報の結果のみを表示する図であり、アンサンブル予報とは無関係である。', explanation: '誤り。スパゲッティ図はまさに複数のアンサンブルメンバーの予測結果を重ねて表示する図であり、単一の決定論的予報の結果のみを示すものではない。' },
      { key: 'C', text: 'スパゲッティ図において線が広く分散している領域ほど、予測の信頼性が高いことを示す。', explanation: '誤り。線が広く分散している（ばらつきが大きい）領域はむしろ予測の不確実性が高い（信頼性が低い）ことを示す。線が密集している領域が信頼性の高い領域である。' },
      { key: 'D', text: 'スパゲッティ図は気温や降水量のような連続的な数値を扱う予測には利用できず、等値線を描ける物理量にのみ限定される特殊な手法である。', explanation: '誤り。スパゲッティ図は本質的に「特定の値の等値線」を重ねて表示する手法であるため、気温や高度、渦度など等値線として表現できる様々な物理量に対して同様に適用可能な、汎用的な可視化手法である。' },
    ],
