    explanation: 'スパゲッティ図はアンサンブル予報の各メンバーが予測する特定の等値線を1枚の図に重ねて表示したもので、線が密集している領域は予測の信頼性が高く、広く分散している領域は予測の不確実性が高いことを視覚的に示す。トラフ・リッジの位置の予測のばらつきを直感的に把握する手法として実技的に活用される。\n\nスパゲッティ図は500 hPa の5700 mや5400 mといった特定の等高度線を各メンバー分重ねて描く。線が束になっていれば予測が一致しており信頼度が高く、ばらけていればトラフの位置などが定まっていないと判断する。\n\n【図解】スパゲッティ図の読み方\n　線の状態｜メンバー間の一致｜予測の信頼度\n　密集している｜一致している｜高い\n　やや広がる｜ある程度の幅｜中程度\n　大きく分散｜ばらばら｜低い\n　⇒ 予測の不確実性が空間のどこで大きいかを一目で把握できる\n　⚠ 線が分散しているほど信頼性が高いとするのは逆である。',
