    explanation: '適中率は予報が的中した事例数を総予報事例数で割った基本的な検証指標で、値が高いほど予報の的中頻度が高いことを示す。ただし出現頻度の低い現象では見かけの適中率が高くなりやすいという限界があるため、バイアススコアなど他の指標と組み合わせた総合的な予報精度の評価が実務上重要とされる。\n\n出現頻度の低い現象では、常に「起こらない」と予報するだけで適中率が高く出てしまう。このため見逃し率や空振り率、バイアススコア、スレットスコアなど複数の指標を組み合わせて評価する必要がある。\n\n【図解】予報の検証指標\n　指標｜意味｜注意点\n　適中率｜的中した割合｜まれな現象で高く出る\n　バイアススコア｜予報数と実況数の比｜1が理想\n　スレットスコア｜的中と空振り見逃しの比｜まれな現象の評価に有効\n　⇒ 単一の指標では予報の有用性は評価しきれない\n　⚠ 適中率は高いほどよい指標であり、低いほど精度が高いのではない。',
