    explanation: '数値予報モデルが物理的に意味のある形で直接表現できる現象の最小水平スケールは、数値解析上の制約から格子間隔のおよそ数倍程度（目安として6〜8倍程度）とされる。これより小さいスケール（サブグリッドスケール）の現象、特に積雲対流は積雲対流パラメタリゼーションなどの近似手法で表現され、モデルの解像度が向上するにつれてこの近似の重要性は相対的に低下していく。\n\n格子間隔と同じ波長の波は2点でしか表現できず、数値的に正しく扱えない。実質的に意味のある表現には格子間隔の6〜8倍が必要とされ、これが有効解像度と呼ばれる。解像度が上がって個々の積乱雲を直接解ければ、対流のパラメタリゼーションは不要になる。\n\n【図解】格子間隔と表現できる現象\n　モデル｜格子間隔｜直接表現できる最小スケール\n　全球モデル｜約13 km｜約80〜100 km\n　メソモデル｜約5 km｜約30〜40 km\n　局地モデル｜約2 km｜約12〜16 km\n　⇒ 有効解像度は格子間隔の6〜8倍程度が目安になる\n　⚠ 積雲対流パラメタリゼーションは、対流を直接解ける解像度では不要になる。',
